const tabLabel: Record<Tab, string> = {
  dashboard: "Dashboard",
  journeys: "Journeys",
  content: "Content",
  calendar: "Calendar",
  contacts: "Contacts",
  settings: "Settings",
};

function formatDate(value: string | null) {
  if (!value) return "Not scheduled";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "Unknown";
  return new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(date);
}

function offsetSchedule(value: string, offsetHours: number) {
  if (!value) return null;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  date.setHours(date.getHours() + offsetHours);
  return date.toISOString();
}

function launchTimingLabel(offsetHours: number) {
  if (offsetHours === 0) return "Main window";
  const absoluteHours = Math.abs(offsetHours);
  const unit = absoluteHours % 24 === 0 ? `${absoluteHours / 24} day${absoluteHours === 24 ? "" : "s"}` : `${absoluteHours}h`;
  return offsetHours < 0 ? `${unit} before` : `${unit} after`;
}

function formatCalendarDay(value: string) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "Unscheduled";
  return new Intl.DateTimeFormat(undefined, { weekday: "short", month: "short", day: "numeric" }).format(date);
}

function formatCalendarTime(value: string | null) {
  if (!value) return "No time";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "Unknown";
  return new Intl.DateTimeFormat(undefined, { hour: "2-digit", minute: "2-digit" }).format(date);
}

function wordCount(value: string) {
  return value.trim().split(/\s+/).filter(Boolean).length;
}

function hasPersonalizationToken(value: string) {
  return /\{\{\s*(first_name|name|full_name)\s*\}\}/i.test(value);
}

function extractPersonalizationTokens(value: string) {
  const tokens: string[] = [];
  const seen = new Set<string>();
  const matcher = /\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g;
  let match = matcher.exec(value);
  while (match) {
    const token = match[1].trim().toLowerCase();
    if (token && !seen.has(token)) {
      seen.add(token);
      tokens.push(token);
    }
    match = matcher.exec(value);
  }
  return tokens;
}

function contactTokenValue(contact: MarketingContact, token: string) {
  const normalized = token.trim().toLowerCase();
  if (normalized === "first_name") return contact.fullName.trim().split(/\s+/)[0] || contact.email?.split("@")[0] || "";
  if (normalized === "name" || normalized === "full_name") return contact.fullName || contact.email || "";
  if (normalized === "email") return contact.email || "";
  if (normalized === "phone" || normalized === "phone_number") return contact.phoneNumber || "";
  if (normalized === "whatsapp" || normalized === "whatsapp_number") return contact.whatsappNumber || contact.phoneNumber || "";
  if (normalized === "company" || normalized === "company_name" || normalized === "organization") return contact.companyName || "";
  if (normalized === "role" || normalized === "role_label") return contact.roleLabel || "";
  if (normalized === "language") return contact.language || "";
  if (normalized === "category") return contact.category || "";
  if (normalized === "vertical") return contact.vertical || "";
  if (normalized === "market") return contact.market || "";
  return "";
}

function personalizePreview(value: string, contact: MarketingContact) {
  return value.replace(/\{\{\s*([a-zA-Z0-9_]+)\s*\}\}/g, (_token, name: string) => {
    const replacement = contactTokenValue(contact, name);
    return replacement || `[${name.trim()}]`;
  });
}

function firstPreviewLine(value: string) {
  return value.split(/\n+/).map((line) => line.trim()).find(Boolean) || "No preview line yet.";
}

function firstMeaningfulPreviewLine(value: string) {
  const lines = value.split(/\n+/).map((line) => line.trim()).filter(Boolean);
  return lines.find((line) => !/^(hi|hello|dear)\b/i.test(line)) ?? lines[0] ?? "No preview line yet.";
}

function plainTextFromHtml(value: string | null | undefined) {
  return (value ?? "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, "\"")
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, " ")
    .trim();
}

function recordTimelineParts(record: { createdAt?: string | null; updatedAt?: string | null; lastSyncedAt?: string | null }) {
  const parts: string[] = [];
  if (record.updatedAt) parts.push(`Updated ${formatDate(record.updatedAt)}`);
  if (record.lastSyncedAt) parts.push(`Synced ${formatDate(record.lastSyncedAt)}`);
  if (!record.updatedAt && !record.lastSyncedAt && record.createdAt) parts.push(`Created ${formatDate(record.createdAt)}`);
  return parts;
}

function calendarDayKey(value: string | null) {
  if (!value) return "unscheduled";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "unscheduled";
  return new Date(date.getFullYear(), date.getMonth(), date.getDate()).toISOString();
}

function statusClass(status: string) {
  if (["published", "active", "succeeded", "opted_in"].includes(status)) return "bg-emerald-50 text-emerald-700";
  if (["scheduled", "running", "pending", "review"].includes(status)) return "bg-sky-50 text-sky-700";
  if (["failed", "opted_out"].includes(status)) return "bg-red-50 text-red-700";
  if (status === "archived") return "bg-slate-100 text-slate-600";
  return "bg-amber-50 text-amber-800";
}

function channelClass(channel: Channel) {
  if (channel === "whatsapp") return "bg-emerald-50 text-emerald-700 border-emerald-100";
  if (channel === "sms" || channel === "phone") return "bg-teal-50 text-teal-700 border-teal-100";
  if (channel === "print") return "bg-orange-50 text-orange-700 border-orange-100";
  if (channel === "event") return "bg-amber-50 text-amber-800 border-amber-100";
  if (channel === "email") return "bg-blue-50 text-blue-700 border-blue-100";
  if (channel === "instagram" || channel === "tiktok") return "bg-pink-50 text-pink-700 border-pink-100";
  if (channel === "linkedin" || channel === "facebook") return "bg-sky-50 text-sky-700 border-sky-100";
  return "bg-purple-50 text-purple-700 border-purple-100";
}

function readinessClass(state: CampaignReadinessState) {
  if (state === "ready") return "border-emerald-200 bg-emerald-50 text-emerald-900";
  if (state === "blocked") return "border-red-200 bg-red-50 text-red-900";
  if (state === "planning") return "border-blue-200 bg-blue-50 text-blue-900";
  return "border-amber-200 bg-amber-50 text-amber-900";
}

function readinessPillClass(state: CampaignReadinessState) {
  if (state === "ready") return "bg-emerald-100 text-emerald-900";
  if (state === "blocked") return "bg-red-100 text-red-900";
  if (state === "planning") return "bg-blue-100 text-blue-900";
  return "bg-amber-100 text-amber-900";
}

function readinessLabel(state: CampaignReadinessState) {
  if (state === "ready") return "Ready";
  if (state === "blocked") return "Blocked";
  if (state === "planning") return "Planning";
  return "Needs action";
}

function lower(value: string | null | undefined) {
  return value?.trim().toLowerCase() ?? "";
}

function lookupKeysForExternalId(value: string | null | undefined, prefixes: string[] = []) {
  const normalized = lower(value);
  if (!normalized) return [];
  const keys = new Set([normalized]);
  const [, suffix] = normalized.includes(":") ? normalized.split(/:(.+)/) : ["", ""];
  if (suffix) keys.add(suffix);
  const base = suffix || normalized;
  for (const prefix of prefixes) {
    keys.add(`${prefix}:${base}`);
  }
  return Array.from(keys);
}

function splitTags(value: string) {
  return value.split(",").map((item) => item.trim()).filter(Boolean);
}

function splitLines(value: string) {
  return Array.from(new Set(value.split(/\r?\n|,/).map((item) => item.trim()).filter(Boolean)));
}

function contactAudienceMemberId(contact: MarketingContact) {
  return contact.lovableExternalId || contact.id;
}

function parseAudienceMemberIds(draft: Pick<AudienceDraft, "contactExternalIds"> | null | undefined) {
  return splitLines(draft?.contactExternalIds ?? "");
}

function updateAudienceDraftMemberIds<T extends AudienceDraft>(draft: T, ids: string[]): T {
  return { ...draft, contactExternalIds: Array.from(new Set(ids.map((id) => id.trim()).filter(Boolean))).join("\n") };
}

function audienceContactLabel(contact: MarketingContact) {
  const name = contact.fullName || contact.email || contact.phoneNumber || contact.whatsappNumber || "Unnamed contact";
  const details = [contact.email, contact.companyName, contact.roleLabel].filter(Boolean).join(" - ");
  return details ? `${name} (${details})` : name;
}

function audienceContactExternalId(contact: MarketingContact, memberIds: string[]) {
  const candidates = [contact.lovableExternalId, contact.id].map((id) => lower(id)).filter(Boolean);
  return memberIds.find((id) => candidates.includes(lower(id))) ?? contact.lovableExternalId ?? contact.id;
}

function contactMatchesMemberIds(contact: MarketingContact, memberIds: string[]) {
  const contactIds = [contact.id, contact.lovableExternalId].map((id) => lower(id)).filter(Boolean);
  return memberIds.some((id) => contactIds.includes(lower(id)));
}

function groupCount<T>(items: T[], keyForItem: (item: T) => string | null | undefined) {
  const result = new Map<string, number>();
  for (const item of items) {
    const key = keyForItem(item);
    if (!key) continue;
    result.set(key, (result.get(key) ?? 0) + 1);
  }
  return result;
}

function parseRulesText(value: string) {
  const trimmed = value.trim();
  if (!trimmed) return {};
  return JSON.parse(trimmed) as Record<string, unknown>;
}

function normalizeCampaignStatus(value: string): CampaignStatus {
  return CAMPAIGN_STATUSES.includes(value as CampaignStatus) ? value as CampaignStatus : "draft";
}

function normalizeJourneyStatus(value: string): JourneyStatus {
  return JOURNEY_STATUSES.includes(value as JourneyStatus) ? value as JourneyStatus : "draft";
}

function normalizeContentStatus(value: string): ContentStatus {
  return CONTENT_STATUSES.includes(value as ContentStatus) ? value as ContentStatus : "draft";
}

function jsonText(value: unknown) {
  if (!value || typeof value !== "object" || Array.isArray(value) || Object.keys(value).length === 0) return "";
  return JSON.stringify(value, null, 2);
}

function jsonArrayText(value: unknown) {
  if (!Array.isArray(value) || value.length === 0) return "";
  return JSON.stringify(value, null, 2);
}

function escapeHtmlText(value: string) {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function emailHtmlFromPlainCopy(body: string) {
  const paragraphs = body.split(/\n{2,}/).map((part) => part.trim()).filter(Boolean);
  if (!paragraphs.length) return "";
  return paragraphs.map((paragraph) => `<p>${escapeHtmlText(paragraph).replace(/\n/g, "<br />")}</p>`).join("");
}

function localizedContentTitle(title: string, languageLabel: string) {
  const trimmedTitle = title.trim() || "Marketing content";
  return /\([^)]+\)$/.test(trimmedTitle) ? `${trimmedTitle} ${languageLabel}` : `${trimmedTitle} (${languageLabel})`;
}

function channelVariantContentTitle(title: string, channelName: string) {
  const trimmedTitle = title.trim() || "Marketing content";
  return `${trimmedTitle} - ${channelName}`;
}

function nextContentVariantChannel(sourceChannel: Channel) {
  return CHANNELS.find((channel) => channel !== sourceChannel) ?? "email";
}

function designShapeSummary(value: unknown) {
  const record = recordValue(value);
  const topLevelKeys = Object.keys(record);
  const arrayKeys = ["blocks", "sections", "elements", "nodes", "components", "rows"]
    .map((key) => ({ key, count: Array.isArray(record[key]) ? (record[key] as unknown[]).length : 0 }))
    .filter((item) => item.count > 0);
  return { topLevelKeys, arrayKeys };
}

function mediaUrlFrom(value: unknown) {
  if (typeof value === "string") return value;
  const record = recordValue(value);
  for (const key of ["url", "originalUrl", "original_url", "src", "href", "assetUrl", "asset_url", "imageUrl", "image_url"]) {
    const url = record[key];
    if (typeof url === "string" && url.trim()) return url.trim();
  }
  return "";
}

function contentMediaPreviewUrls(content: ContentAsset, linkedAssets: MarketingMediaAsset[]) {
  const embedded = Array.isArray(content.mediaAssets) ? content.mediaAssets.map(mediaUrlFrom) : [];
  const linked = linkedAssets.flatMap((asset) => [asset.originalUrl, asset.localUrl ?? ""]);
  return Array.from(new Set([...embedded, ...linked].map((url) => url.trim()).filter(Boolean)));
}

function campaignChannelHandoffBrief(
  campaign: Campaign,
  channel: Channel,
  contentAsset: ContentAsset,
  linkedAssets: MarketingMediaAsset[],
  recipients: number,
  scheduledAt: string | null,
) {
  const designBlocks = collectDesignPreviewBlocks(contentAsset.designJson ?? {});
  const leadBlock = designBlocks.find((block) => block.title || block.body || block.ctaLabel || block.ctaUrl) ?? null;
  const mediaUrls = contentMediaPreviewUrls(contentAsset, linkedAssets);
  const hook = contentAsset.subject || leadBlock?.title || contentAsset.title;
  const body = contentAsset.body || leadBlock?.body || "";
  const ctaLabel = contentAsset.ctaLabel || leadBlock?.ctaLabel || "";
  const ctaUrl = contentAsset.ctaUrl || leadBlock?.ctaUrl || "";
  const lines = [
    `Campaign: ${campaign.name}`,
    `Channel: ${channelLabel[channel]}`,
    `Audience: ${campaign.audienceType.toUpperCase()}`,
    `Status: ${campaign.status}`,
    `Schedule: ${formatDate(scheduledAt || campaign.scheduleStartsAt)}`,
    `Recipients/list size: ${recipients}`,
    campaign.objective ? `Objective: ${campaign.objective}` : "",
    hook ? `Hook/subject: ${hook}` : "",
    body ? `Copy:\n${body}` : "",
    ctaLabel || ctaUrl ? `CTA: ${[ctaLabel, ctaUrl].filter(Boolean).join(" - ")}` : "",
    mediaUrls.length ? `Media:\n${mediaUrls.map((url) => `- ${url}`).join("\n")}` : "",
    contentAsset.lovableExternalId ? `Source content ID: ${contentAsset.lovableExternalId}` : "",
  ];
  return lines.filter(Boolean).join("\n\n");
}

function campaignChannelPublishCopy(
  channel: Channel,
  contentAsset: ContentAsset,
  linkedAssets: MarketingMediaAsset[],
) {
  const designBlocks = collectDesignPreviewBlocks(contentAsset.designJson ?? {});
  const leadBlock = designBlocks.find((block) => block.title || block.body || block.ctaLabel || block.ctaUrl) ?? null;
  const mediaUrls = contentMediaPreviewUrls(contentAsset, linkedAssets);
  const hook = contentAsset.subject || leadBlock?.title || "";
  const body = contentAsset.body || plainTextFromHtml(contentAsset.htmlBody) || leadBlock?.body || "";
  const ctaLabel = contentAsset.ctaLabel || leadBlock?.ctaLabel || "";
  const ctaUrl = contentAsset.ctaUrl || leadBlock?.ctaUrl || "";
  const includeSubject = channel === "email";
  const cta = ctaLabel || ctaUrl ? `${ctaLabel || "Learn more"}${ctaUrl ? `: ${ctaUrl}` : ""}` : "";
  const lines = [
    includeSubject && hook ? `Subject: ${hook}` : "",
    !includeSubject && hook && hook.trim() !== body.trim() ? hook : "",
    body,
    cta,
    mediaUrls.length ? `Media refs:\n${mediaUrls.map((url) => `- ${url}`).join("\n")}` : "",
  ].filter(Boolean);
  return (lines.length ? lines : [contentAsset.title]).join("\n\n");
}

function isPreviewableImageUrl(url: string) {
  return /^data:image\//i.test(url) || /\.(png|jpe?g|gif|webp|avif|svg)(?:[?#].*)?$/i.test(url);
}

function isPreviewableVideoUrl(url: string) {
  return /^data:video\//i.test(url) || /\.(mp4|webm|ogg|mov|m4v)(?:[?#].*)?$/i.test(url);
}

function mediaPreviewLabel(url: string) {
  try {
    const parsed = new URL(url);
    return parsed.pathname.split("/").filter(Boolean).pop() || parsed.hostname;
  } catch {
    return url;
  }
}

const designPreviewArrayKeys = ["blocks", "sections", "elements", "nodes", "components", "rows", "children", "items"] as const;
const designPreviewObjectKeys = ["content", "props", "settings", "data", "attributes", "style", "styles"] as const;
const designPreviewTitleKeys = ["headline", "heading", "title", "subject", "name", "label"] as const;
const designPreviewBodyKeys = ["body", "copy", "text", "description", "caption", "message", "content", "plainText", "plain_text", "subtitle"] as const;
const designPreviewCtaLabelKeys = ["ctaLabel", "cta_label", "buttonText", "button_text", "buttonLabel", "button_label", "linkText", "link_text"] as const;
const designPreviewCtaUrlKeys = ["ctaUrl", "cta_url", "buttonUrl", "button_url", "linkUrl", "link_url", "href", "url"] as const;
const designPreviewMediaKeys = ["imageUrl", "image_url", "src", "assetUrl", "asset_url", "mediaUrl", "media_url", "videoUrl", "video_url", "thumbnailUrl", "thumbnail_url", "coverImageUrl", "cover_image_url"] as const;

type DesignPreviewBlock = {
  key: string;
  type: string;
  title: string;
  body: string;
  mediaUrl: string;
  ctaLabel: string;
  ctaUrl: string;
};

function parsedDesignValue(value: unknown): unknown {
  if (typeof value !== "string") return value;
  const trimmed = value.trim();
  if (!trimmed || !/^[{[]/.test(trimmed)) return value;
  try {
    return JSON.parse(trimmed) as unknown;
  } catch {
    return value;
  }
}

function designRecordText(record: Record<string, unknown>, keys: readonly string[]) {
  for (const key of keys) {
    const value = parsedDesignValue(record[key]);
    if (typeof value === "string" && value.trim()) return value.trim();
    if (typeof value === "number" || typeof value === "boolean") return String(value);
  }
  return "";
}

function designRecordMediaUrl(record: Record<string, unknown>) {
  for (const key of designPreviewMediaKeys) {
    const value = parsedDesignValue(record[key]);
    if (typeof value === "string" && value.trim()) return value.trim();
    if (value && typeof value === "object") {
      const nested = mediaUrlFrom(value);
      if (nested) return nested;
    }
  }
  return "";
}

function collectDesignPreviewBlocks(value: unknown, path = "design", seen = new Set<unknown>()): DesignPreviewBlock[] {
  const parsed = parsedDesignValue(value);
  if (!parsed || typeof parsed !== "object") return [];
  if (seen.has(parsed)) return [];
  seen.add(parsed);

  if (Array.isArray(parsed)) {
    return parsed.flatMap((item, index) => collectDesignPreviewBlocks(item, `${path}.${index}`, seen));
  }

  const record = parsed as Record<string, unknown>;
  const title = designRecordText(record, designPreviewTitleKeys);
  const body = designRecordText(record, designPreviewBodyKeys);
  const mediaUrl = designRecordMediaUrl(record);
  const ctaLabel = designRecordText(record, designPreviewCtaLabelKeys);
  const ctaUrl = designRecordText(record, designPreviewCtaUrlKeys);
  const type = designRecordText(record, ["type", "kind", "component", "blockType", "block_type"]) || "Block";
  const current = title || body || mediaUrl || ctaLabel || ctaUrl
    ? [{ key: path, type, title, body, mediaUrl, ctaLabel, ctaUrl }]
    : [];
  const children = [
    ...designPreviewArrayKeys.flatMap((key) => collectDesignPreviewBlocks(record[key], `${path}.${key}`, seen)),
    ...designPreviewObjectKeys.flatMap((key) => collectDesignPreviewBlocks(record[key], `${path}.${key}`, seen)),
  ];
  return [...current, ...children];
}

const lovableContentSourceLabels: Record<string, string> = {
  content: "Content",
  content_asset: "Content asset",
  saved_email_template: "Saved email template",
  template: "Template",
  content_brief: "Content brief",
  journey_step_preset: "Journey step preset",
  social_post: "Social post",
  missing_lovable_reference: "Missing Source reference",
  source_repaired_draft: "Source repair draft",
};

function metadataString(value: unknown, key: string) {
  const item = recordValue(value)[key];
  return typeof item === "string" && item.trim() ? item.trim() : "";
}

function contentOriginKey(item: ContentAsset) {
  const sourceType = metadataString(item.metadata, "lovable_source_type");
  if (sourceType) return sourceType;
  return item.source || "vyva";
}

function contentSourceLabel(key: string) {
  if (key === "vyva") return "VYVA";
  if (key === "lovable") return "Source content";
  return lovableContentSourceLabels[key] ?? key.replace(/_/g, " ");
}

function contentOriginLabel(item: ContentAsset) {
  const sourceType = contentOriginKey(item);
  if (sourceType) return contentSourceLabel(sourceType);
  if (item.source === "lovable") return "Source content";
  return item.source;
}

function contentAssetHasCopy(item: ContentAsset) {
  return Boolean(
    (item.subject ?? "").trim()
    || (item.body ?? "").trim()
    || (item.htmlBody ?? "").trim(),
  );
}

const lovableContentSourceDetailKeys = [
  "id",
  "title",
  "name",
  "templateName",
  "template_name",
  "subject",
  "subjectLine",
  "subject_line",
  "channel",
  "platform",
  "network",
  "language",
  "locale",
  "status",
  "audienceType",
  "audience_type",
  "campaignId",
  "campaign_id",
  "journeyId",
  "journey_id",
  "templateKind",
  "template_kind",
  "tags",
  "hashtags",
  "category",
  "updatedAt",
  "updated_at",
  "createdAt",
  "created_at",
] as const;

function humanizeMetadataKey(key: string) {
  return key
    .replace(/_/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/^./, (match) => match.toUpperCase());
}

function sourceDetailParsedValue(value: unknown) {
  if (typeof value !== "string") return value;
  const trimmed = value.trim();
  if (!trimmed || !/^[{[]/.test(trimmed)) return value;
  try {
    return JSON.parse(trimmed) as unknown;
  } catch {
    return value;
  }
}

function sourceDetailText(value: unknown) {
  const parsed = sourceDetailParsedValue(value);
  if (parsed === null || parsed === undefined) return "";
  if (typeof parsed === "string") return parsed.trim();
  if (typeof parsed === "number" || typeof parsed === "boolean") return String(parsed);
  if (Array.isArray(parsed)) {
    const values = parsed
      .map((item) => sourceDetailText(item))
      .filter(Boolean);
    return values.length ? values.slice(0, 8).join(", ") : "";
  }
  return "";
}

function sourceDetailDisplayValue(key: string, value: unknown) {
  const text = sourceDetailText(value);
  if (!text) return "";
  if (/(^|_|\b)(created|updated|scheduled|published|sent|date|at)(_|$|\b)/i.test(key)) {
    const formatted = formatDate(text);
    if (formatted !== "Unknown" && formatted !== "Not scheduled") return formatted;
  }
  return text.length > 220 ? `${text.slice(0, 217)}...` : text;
}

function lovableContentSourceDetails(content: ContentAsset) {
  const metadata = recordValue(content.metadata);
  const lovable = recordValue(metadata.lovable);
  if (content.source !== "lovable" && Object.keys(lovable).length === 0) return [];
  const rows = new Map<string, string>();
  if (content.lovableExternalId) rows.set("Source ID", content.lovableExternalId);
  rows.set("Source type", contentOriginLabel(content));
  if (content.updatedAt) rows.set("VYVA updated", formatDate(content.updatedAt));
  if (content.createdAt) rows.set("VYVA created", formatDate(content.createdAt));
  for (const key of lovableContentSourceDetailKeys) {
    const value = sourceDetailDisplayValue(key, lovable[key]);
    if (value) rows.set(humanizeMetadataKey(key), value);
  }
  return Array.from(rows, ([label, value]) => ({ label, value }));
}

function contentAssetByReference(content: ContentAsset[], reference?: string | null) {
  const normalized = lower(reference);
  if (!normalized) return null;
  return content.find((item) => [
    item.id,
    item.lovableExternalId ?? "",
    `content:${item.lovableExternalId ?? ""}`,
    `content_asset:${item.lovableExternalId ?? ""}`,
    `saved_email_template:${item.lovableExternalId ?? ""}`,
    `social_post:${item.lovableExternalId ?? ""}`,
    `template:${item.lovableExternalId ?? ""}`,
    `content_brief:${item.lovableExternalId ?? ""}`,
  ].some((candidate) => lower(candidate) === normalized)) ?? null;
}

function contentReferenceKeys(content: ContentAsset) {
  const keys = new Set<string>();
  const prefixes = ["content", "content_asset", "saved_email_template", "social_post", "template", "content_brief", "journey_step_preset"];
  for (const value of [content.id, content.lovableExternalId]) {
    for (const key of lookupKeysForExternalId(value, prefixes)) keys.add(key);
  }
  return keys;
}

function contentReferenceMatches(content: ContentAsset, reference?: string | null) {
  const normalized = lower(reference);
  if (!normalized) return false;
  const keys = contentReferenceKeys(content);
  if (keys.has(normalized)) return true;
  const [, suffix] = normalized.includes(":") ? normalized.split(/:(.+)/) : ["", ""];
  return Boolean(suffix && keys.has(suffix));
}

function contentUsageFor(content: ContentAsset, campaigns: Campaign[], journeys: Journey[]): ContentUsage[] {
  const usages: ContentUsage[] = [];
  const seen = new Set<string>();
  for (const campaign of campaigns) {
    for (const channel of campaign.channels ?? []) {
      if (!contentReferenceMatches(content, channel.contentAssetId)) continue;
      const key = `campaign:${campaign.id}:${channel.id}`;
      if (seen.has(key)) continue;
      seen.add(key);
      usages.push({
        key,
        kind: "campaign",
        campaignId: campaign.id,
        label: campaign.name,
        detail: `${channelLabel[channel.channel]} campaign channel${channel.scheduledAt ? ` / ${formatDate(channel.scheduledAt)}` : ""}`,
        channel: channel.channel,
        status: channel.status || campaign.status,
      });
    }
  }
  for (const journey of journeys) {
    for (const step of journey.steps ?? []) {
      if (!contentReferenceMatches(content, step.contentAssetId) && !contentReferenceMatches(content, step.templateRef)) continue;
      const key = `journey:${journey.id}:${step.id}`;
      if (seen.has(key)) continue;
      seen.add(key);
      usages.push({
        key,
        kind: "journey",
        journeyId: journey.id,
        label: journey.name,
        detail: `Step ${step.stepOrder + 1}: ${step.kind || "message"} / ${channelLabel[step.channel]} / day ${step.dayOffset}`,
        channel: step.channel,
        status: step.status || journey.status,
      });
    }
  }
  return usages;
}

function newDraftId() {
  return `draft-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

