const contentTemplateCategories = Array.from(new Set(contentTemplateGallery.map((template) => template.category))).sort();

function newCampaignChannelDraft(channel: Channel = "email", status: CampaignStatus = "draft", scheduledAt = ""): CampaignChannelDraft {
  return {
    id: newDraftId(),
    channel,
    contentAssetId: "",
    status,
    scheduledAt,
  };
}

function campaignDraftChannels(draft: Pick<CampaignDraft, "channel" | "channels">): Channel[] {
  const channels = [draft.channel, ...(draft.channels ?? [])]
    .filter((channel): channel is Channel => CHANNELS.includes(channel as Channel));
  return Array.from(new Set(channels));
}

function emptyCampaignDraft(): CampaignDraft {
  return {
    name: "",
    audienceType: "b2c",
    channel: "email",
    channels: ["email"],
    contentAssetId: "",
    channelContentAssetIds: {},
    status: "draft",
    scheduleStartsAt: "",
    scheduleEndsAt: "",
    objective: "",
    targetAudienceId: "",
    recipientFilter: "",
    snapshotRecipients: false,
  };
}

function emptyContentDraft(): ContentDraft {
  return {
    title: "",
    channel: "email",
    language: "en",
    status: "draft",
    subject: "",
    body: "",
    htmlBody: "",
    ctaLabel: "",
    ctaUrl: "",
    designJsonText: "{}",
    mediaAssetsText: "[]",
  };
}

function contentDraftFromTemplate(template: ContentTemplate): ContentDraft {
  return {
    title: template.title,
    channel: template.channel,
    language: "en",
    status: "draft",
    subject: template.subject,
    body: template.body,
    htmlBody: template.htmlBody ?? "",
    ctaLabel: template.ctaLabel,
    ctaUrl: template.ctaUrl,
    designJsonText: JSON.stringify(template.designJson, null, 2),
    mediaAssetsText: JSON.stringify(template.mediaAssets ?? [], null, 2),
  };
}

function templateDesignItemText(value: unknown) {
  const direct = displayText(value);
  if (direct) return direct;
  const record = recordValue(value);
  const primary = displayText(record.text)
    || displayText(record.title)
    || displayText(record.heading)
    || displayText(record.label)
    || displayText(record.name)
    || displayText(record.type)
    || displayText(record.kind);
  const items = Array.isArray(record.items)
    ? record.items.map(displayText).filter(Boolean).slice(0, 3).join(", ")
    : "";
  if (primary && items) return `${primary}: ${items}`;
  return primary || items;
}

function templateDesignItems(value: unknown, limit = 4) {
  return Array.isArray(value)
    ? value.map(templateDesignItemText).filter(Boolean).slice(0, limit)
    : [];
}

function contentTemplateDesignBrief(template: ContentTemplate) {
  const design = recordValue(template.designJson);
  const layout = displayText(design.layout);
  const tone = displayText(design.tone);
  const visual = displayText(design.visualPrompt);
  const proof = displayText(design.proofPoint);
  const fields = templateDesignItems(design.mergeFields, 4);
  const slides = templateDesignItems(design.slides, 4);
  const beats = templateDesignItems(design.beats, 4);
  const blocks = templateDesignItems(design.blocks, 4);
  const structure = slides.length
    ? { label: "Slides", items: slides }
    : beats.length
      ? { label: "Beats", items: beats }
      : blocks.length
        ? { label: "Blocks", items: blocks }
        : null;

  const tags = [
    layout ? `Layout: ${layout}` : "",
    tone ? `Tone: ${tone}` : "",
    proof ? `Proof: ${proof}` : "",
    fields.length ? `Fields: ${fields.join(", ")}` : "",
  ].filter(Boolean);

  return {
    tags,
    visual,
    structure,
    hasBrief: Boolean(tags.length || visual || structure),
  };
}

const templatePreviewFallbackPalettes: Record<Channel, string[]> = {
  email: ["#6d28d9", "#fff7ed", "#10b981"],
  whatsapp: ["#059669", "#ecfdf5", "#6d28d9"],
  sms: ["#2563eb", "#eff6ff", "#6d28d9"],
  phone: ["#7c2d12", "#fff7ed", "#f59e0b"],
  print: ["#241133", "#f5eee8", "#8b5cf6"],
  event: ["#0f766e", "#ecfeff", "#f59e0b"],
  facebook: ["#2563eb", "#eff6ff", "#6d28d9"],
  instagram: ["#db2777", "#fdf2f8", "#f59e0b"],
  linkedin: ["#0369a1", "#e0f2fe", "#6d28d9"],
  tiktok: ["#111827", "#f9fafb", "#db2777"],
};

function safeTemplatePreviewColor(value: unknown, fallback: string) {
  const text = displayText(value);
  return /^#[0-9a-fA-F]{6}$/.test(text) ? text : fallback;
}

function contentTemplatePreviewPalette(template: ContentTemplate) {
  const design = recordValue(template.designJson);
  const fallback = templatePreviewFallbackPalettes[template.channel];
  const palette = Array.isArray(design.palette)
    ? design.palette
      .map((value, index) => safeTemplatePreviewColor(value, fallback[index] ?? fallback[0]))
      .filter(Boolean)
    : [];
  return [...palette, ...fallback].slice(0, 3);
}

function contentTemplatePreviewLines(template: ContentTemplate, designBrief: ReturnType<typeof contentTemplateDesignBrief>) {
  const structureLines = (designBrief.structure?.items ?? []).slice(0, 2);
  return [
    template.subject,
    firstMeaningfulPreviewLine(template.body || template.description),
    ...structureLines,
    template.ctaLabel ? `CTA: ${template.ctaLabel}` : "",
  ].filter(Boolean).slice(0, 5);
}

function templatePackAiCommandText(pack: ContentTemplatePack, templates: ContentTemplate[]) {
  const channels = Array.from(new Set(templates.map((template) => template.channel)));
  const audiences = Array.from(new Set(templates.map((template) => template.audienceType)));
  const categories = Array.from(new Set(templates.map((template) => template.category)));
  const sequence = pack.sequence.map((step, index) => (
    `${index + 1}. ${step.offset} / ${channelLabel[step.channel]} / ${step.title}: ${step.detail}`
  ));
  const templateLines = templates.map((template) => {
    const firstBodyLine = template.body.split(/\n+/).map((line) => line.trim()).find(Boolean) ?? "No body yet.";
    const subject = template.subject ? ` Subject: ${template.subject}.` : "";
    const cta = template.ctaLabel ? ` CTA: ${template.ctaLabel}${template.ctaUrl ? ` -> ${template.ctaUrl}` : ""}.` : "";
    return `- ${template.title} (${channelLabel[template.channel]}, ${template.audienceType.toUpperCase()}, ${template.category}).${subject} ${firstBodyLine}${cta}`;
  });

  return [
    "VYVA template pack AI command",
    `Pack: ${pack.title}`,
    `Focus: ${pack.focus}`,
    `Audience fit: ${audiences.map((audience) => audience.toUpperCase()).join(", ") || "Not set"}`,
    `Channels: ${channels.map((channel) => channelLabel[channel]).join(", ") || "Not set"}`,
    `Categories: ${categories.join(", ") || "Not set"}`,
    `Goal: ${pack.description}`,
    `Recommended sequence:\n${sequence.join("\n") || "No sequence yet."}`,
    `Available templates:\n${templateLines.join("\n") || "No templates yet."}`,
    `Base pack prompt:\n${pack.aiPrompt}`,
    "AI task: Adapt this pack into a polished, publish-ready campaign plan. Return the campaign objective, audience segment, channel-specific copy, schedule, visual direction, approval checklist, publishing handoff, and relationship follow-up. Keep VYVA's tone warm, practical, consent-aware, and non-clinical.",
  ].join("\n\n");
}

function ContentTemplateVisualPreview({
  template,
  designBrief,
}: {
  template: ContentTemplate;
  designBrief: ReturnType<typeof contentTemplateDesignBrief>;
}) {
  const design = recordValue(template.designJson);
  const layout = displayText(design.layout) || `${channelLabel[template.channel]} layout`;
  const palette = contentTemplatePreviewPalette(template);
  const lines = contentTemplatePreviewLines(template, designBrief);
  const visualCue = designBrief.visual || displayText(design.visualPrompt) || displayText(design.proofPoint) || template.description;
  const headline = template.subject || `${channelLabel[template.channel]} starter`;

  return (
    <div
      className="mt-3 overflow-hidden rounded-xl border border-purple-100 bg-[#fffaf4] shadow-sm"
      data-testid={`marketing-content-template-visual-preview-${template.id}`}
    >
      <div
        className="h-2"
        style={{ background: `linear-gradient(90deg, ${palette[0]}, ${palette[1]}, ${palette[2]})` }}
        aria-hidden="true"
      />
      <div className="grid gap-3 p-3">
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <p className="truncate text-[11px] font-black uppercase tracking-[0.1em] text-purple-700">{layout}</p>
            <p className="mt-1 line-clamp-2 text-sm font-black leading-snug text-[#241133]">{headline}</p>
          </div>
          <div className="flex shrink-0 gap-1" data-testid={`marketing-content-template-palette-${template.id}`}>
            {palette.map((color) => (
              <span
                key={color}
                className="h-5 w-5 rounded-full border border-white shadow-sm"
                style={{ backgroundColor: color }}
                aria-label={`Template color ${color}`}
              />
            ))}
          </div>
        </div>
        <div className="grid gap-1.5" data-testid={`marketing-content-template-preview-lines-${template.id}`}>
          {lines.map((line, index) => (
            <p key={`${template.id}-preview-line-${index}`} className={`rounded-lg px-3 py-2 text-xs font-bold leading-relaxed ${index === 0 ? "bg-white text-[#241133]" : "bg-[#fbf7f2] text-[#6f5f59]"}`}>
              {line}
            </p>
          ))}
        </div>
        {visualCue ? (
          <p className="line-clamp-2 rounded-lg border border-purple-100 bg-white px-3 py-2 text-xs font-semibold leading-relaxed text-[#6f5f59]">
            Visual: {visualCue}
          </p>
        ) : null}
      </div>
    </div>
  );
}

function contentAssetMatchesTemplatePack(content: ContentAsset, pack: ContentTemplatePack, template: ContentTemplate) {
  if (content.channel !== template.channel || content.status === "archived") return false;
  const metadata = recordValue(content.metadata);
  const designJson = recordValue(content.designJson);
  const lovableId = lower(content.lovableExternalId);
  const templateRefs = [
    template.id,
    `template:${template.id}`,
    `content_template:${template.id}`,
    `saved_email_template:${template.id}`,
    `social_post:${template.id}`,
  ].map(lower);
  const metadataTemplateId = lower(displayText(metadata.templateId));
  const metadataPackId = lower(displayText(metadata.packId));
  const designTemplateId = lower(displayText(designJson.templateId));
  const titleMatches = lower(content.title) === lower(template.title);
  return templateRefs.includes(lovableId)
    || templateRefs.includes(metadataTemplateId)
    || templateRefs.includes(designTemplateId)
    || (metadataPackId === lower(pack.id) && (metadataTemplateId === lower(template.id) || titleMatches));
}

function scheduleWithDelay(baseIso: string | null, delayHours: number) {
  if (!baseIso) return null;
  const date = new Date(baseIso);
  if (Number.isNaN(date.getTime())) return null;
  date.setHours(date.getHours() + Math.max(0, delayHours));
  return date.toISOString();
}

function templatePackRouteSendMode(channel: Channel) {
  if (channel === "email") return "VYVA email review/send";
  if (channel === "whatsapp") return "WhatsApp relationship handoff until provider dispatch is enabled";
  if (channel === "phone") return "Human call task";
  if (channel === "print") return "Print/offline handoff";
  if (channel === "event") return "Event/community handoff";
  if (channel === "sms") return "SMS planning record";
  return "Manual social publishing/tracking";
}

function templatePackRouteOwner(channel: Channel) {
  if (channel === "email") return "Marketing admin";
  if (channel === "whatsapp" || channel === "phone") return "Relationship owner";
  if (channel === "print" || channel === "event") return "Local operations";
  return "Social/content owner";
}

function templatePackRouteNextAction(channel: Channel, hasContent: boolean, recipientCount: number) {
  if (!hasContent) return `Attach ${channelLabel[channel]} content before launch.`;
  if (channel === "email") {
    return recipientCount > 0
      ? "Review content, send a test, then use explicit VYVA email send."
      : "Review content, snapshot recipients, send a test, then send explicitly.";
  }
  if (channel === "whatsapp") return "Preview copy, publish manually, and track replies in the campaign.";
  if (channel === "phone") return "Turn the message into a call list and log outcomes.";
  if (channel === "print") return "Export the copy into print collateral and track distribution.";
  if (channel === "event") return "Use as event promotion or follow-up notes and track RSVPs.";
  return "Preview the content, publish in the platform, then save the result in VYVA.";
}

function buildTemplatePackLaunchPacket({
  pack,
  audienceType,
  targetAudience,
  scheduleStartsAt,
  routeChannels,
  routeTemplateByChannel,
  contentByTemplateId,
  channels,
  recipients,
}: {
  pack: ContentTemplatePack;
  audienceType: Audience;
  targetAudience: Record<string, unknown> | null;
  scheduleStartsAt: string | null;
  routeChannels: Channel[];
  routeTemplateByChannel: Map<Channel, ContentTemplate>;
  contentByTemplateId: Map<string, ContentAsset>;
  channels: Array<{ channel: Channel; contentAssetId: string | null; status: string; scheduledAt: string | null; sendCapability: string }>;
  recipients: Array<{ channel: Channel }>;
}): TemplatePackLaunchPacket {
  const channelPlans = routeChannels.map((channel) => {
    const template = routeTemplateByChannel.get(channel) ?? null;
    const contentAsset = template ? contentByTemplateId.get(template.id) ?? null : null;
    const channelPlan = channels.find((item) => item.channel === channel);
    const recipientCount = recipients.filter((recipient) => recipient.channel === channel).length;
    return {
      channel,
      channelLabel: channelLabel[channel],
      scheduledAt: channelPlan?.scheduledAt ?? scheduleStartsAt,
      contentAssetId: contentAsset?.id ?? channelPlan?.contentAssetId ?? null,
      contentTitle: contentAsset?.title ?? template?.title ?? "No content linked",
      templateId: template?.id ?? null,
      templateTitle: template?.title ?? "No template linked",
      sendMode: templatePackRouteSendMode(channel),
      owner: templatePackRouteOwner(channel),
      nextAction: templatePackRouteNextAction(channel, Boolean(contentAsset ?? channelPlan?.contentAssetId), recipientCount),
      recipientCount,
      status: channelPlan?.status ?? "draft",
    };
  });

  const channelNames = channelPlans.map((item) => item.channelLabel).join(" + ");
  const hasSocial = routeChannels.some((channel) => ["facebook", "instagram", "linkedin", "tiktok"].includes(channel));
  const hasDirect = routeChannels.some((channel) => ["whatsapp", "sms", "phone", "print"].includes(channel));

  return {
    version: 1,
    generatedFrom: "template_pack_campaign_plan",
    packId: pack.id,
    packTitle: pack.title,
    focus: pack.focus,
    audienceType,
    targetAudience,
    scheduleStartsAt,
    routeSummary: `${channelNames || "No channels"} plan with ${recipients.length} planned recipient route${recipients.length === 1 ? "" : "s"}.`,
    channels: channelPlans,
    reviewChecklist: [
      "Review every linked content asset before launch.",
      "Confirm the target list and mapped contacts.",
      "Save or refresh recipient snapshots before any email send.",
      "Send a test email when the route includes Email.",
      "Use manual tracking for social, WhatsApp, phone, print, and event handoffs.",
      "Log outcomes so follow-up campaigns can use real relationship signals.",
    ],
    visualBriefs: [
      {
        key: "hero",
        title: "Campaign hero",
        format: "Email/social hero",
        text: `Create a warm VYVA visual for "${pack.title}" focused on: ${pack.focus}`,
      },
      ...(hasSocial ? [{
        key: "social",
        title: "Social creative set",
        format: "Square post + short caption visual",
        text: `Turn "${pack.description}" into a clear social proof visual for ${routeChannels.filter((channel) => ["facebook", "instagram", "linkedin", "tiktok"].includes(channel)).map((channel) => channelLabel[channel]).join(", ")}.`,
      }] : []),
      ...(hasDirect ? [{
        key: "direct",
        title: "Direct outreach card",
        format: "WhatsApp/phone/print handoff",
        text: "Prepare a concise human follow-up card with the promise, CTA, and one note field for the relationship owner.",
      }] : []),
    ],
    followUpPlays: [
      {
        key: "reply",
        trigger: "Reply, comment, or WhatsApp response",
        owner: "Relationship owner",
        action: "Move the contact into a warm follow-up and respond with one practical next step.",
      },
      {
        key: "click",
        trigger: "Email click or social engagement",
        owner: "Marketing admin",
        action: "Create a smaller proof or demo follow-up using the same offer.",
      },
      {
        key: "no-response",
        trigger: "No signal after 5-7 days",
        owner: "Marketing admin",
        action: "Rework the CTA or move to a lighter channel before repeating.",
      },
    ],
    outcomeTrackers: [
      { key: "reach", metric: "Reach / saved recipients", target: "Know exactly who was planned or reached.", source: "recipient snapshots and manual results" },
      { key: "response", metric: "Replies, clicks, and social engagement", target: "Identify warm relationships for follow-up.", source: "campaign metrics and tracked manual outcomes" },
      { key: "handoff", metric: "Manual handoff completion", target: "Avoid losing non-email campaign work outside VYVA.", source: "manual publish tracker" },
    ],
    aiPrompt: pack.aiPrompt,
  };
}

function experimentCtaLabel(content: ContentAsset | null, campaign: Campaign) {
  const current = lower(content?.ctaLabel ?? "");
  if (current.includes("demo") || campaign.audienceType === "b2b") return "Book a VYVA demo";
  if (current.includes("open")) return "Open VYVA now";
  if (current.includes("read")) return "See the next step";
  return "Take the next step";
}

function contentDraftFromCampaignExperiment(
  campaign: Campaign,
  content: ContentAsset,
  suggestion: CampaignExperimentSuggestion,
): ContentDraft {
  const experimentName = suggestion.experimentType === "subject"
    ? "subject line test"
    : suggestion.experimentType === "cta"
      ? "CTA test"
      : "follow-up test";
  const ctaLabel = suggestion.experimentType === "cta" ? experimentCtaLabel(content, campaign) : content.ctaLabel ?? "";
  const subject = suggestion.experimentType === "subject"
    ? `${content.subject || campaign.name}: one clear next step`
    : content.subject ?? "";
  const bodyNote = suggestion.experimentType === "cta"
    ? "\n\nExperiment note: Use one direct call to action and remove secondary asks."
    : suggestion.experimentType === "follow_up"
      ? "\n\nExperiment note: Follow up with the same audience using the winning angle and one fresh proof point."
      : "\n\nExperiment note: Test a clearer subject line against the imported baseline.";

  return {
    title: `${content.title} - ${experimentName}`,
    channel: content.channel,
    language: content.language || "en",
    status: "draft",
    subject,
    body: `${content.body}${bodyNote}`,
    htmlBody: content.htmlBody ?? "",
    ctaLabel,
    ctaUrl: content.ctaUrl ?? "",
    designJsonText: jsonText({
      ...(content.designJson ?? {}),
      experiment: {
        type: suggestion.experimentType,
        campaignId: campaign.id,
        campaignName: campaign.name,
        sourceMetric: suggestion.key,
        recommendation: suggestion.title,
        reason: suggestion.detail,
      },
      generator: "marketing_performance_experiment",
    }),
    mediaAssetsText: jsonArrayText(content.mediaAssets),
  };
}

function campaignIntentBriefFromExperiment(
  campaign: Campaign,
  content: ContentAsset,
  suggestion: CampaignExperimentSuggestion,
  targetAudience: MarketingAudience | null,
) {
  const experimentLabel = suggestion.experimentType === "subject"
    ? "subject line clarity test"
    : suggestion.experimentType === "cta"
      ? "CTA clarity test"
      : "winner follow-up";
  const aiDirection = suggestion.experimentType === "subject"
    ? "Write a subject-led variant that makes the benefit clearer before opening."
    : suggestion.experimentType === "cta"
      ? "Write a variant with one direct call to action, one obvious button label, and no competing asks."
      : "Write a warm follow-up that reuses the winning angle and adds one fresh proof point.";
  const audienceLabel = targetAudience?.name ?? campaign.audienceType.toUpperCase();
  const routeLabel = campaign.channels.length
    ? campaign.channels.map((channel) => channelLabel[channel.channel]).join(" + ")
    : channelLabel[content.channel];

  return [
    `Performance experiment from "${campaign.name}".`,
    `Signal: ${suggestion.value}. ${suggestion.detail}`,
    `Experiment: ${experimentLabel}.`,
    `Audience/list: ${audienceLabel}.`,
    `Primary channel: ${channelLabel[content.channel]}. Current campaign route: ${routeLabel}.`,
    content.subject ? `Current hook: "${content.subject}".` : "",
    content.ctaLabel ? `Current CTA: ${content.ctaLabel}.` : "",
    `AI direction: ${aiDirection}`,
    "Goal: create the next campaign/content variant, compare it against the imported performance baseline, and keep the audience experience focused.",
  ].filter(Boolean).join("\n");
}

function contentDraftFromCampaignDraft(draft: CampaignDraft, targetAudience: MarketingAudience | null): ContentDraft {
  const campaignName = draft.name.trim() || `${channelLabel[draft.channel]} campaign`;
  const objective = draft.objective.trim() || "Share one clear VYVA benefit and invite the audience to take the next step.";
  const audienceLabel = targetAudience?.name ?? (draft.audienceType === "b2b" ? "B2B contacts" : draft.audienceType === "b2c" ? "B2C contacts" : "mixed audience");
  const ctaLabel = draft.audienceType === "b2b" ? "Book a demo" : "Open VYVA";
  const ctaUrl = draft.audienceType === "b2b" ? "https://v2.vyva.life/demo" : "https://v2.vyva.life";
  const channelName = channelLabel[draft.channel];
  const body = draft.channel === "email"
    ? [
      "Hi {{first_name}},",
      "",
      objective,
      "",
      "VYVA helps families and care teams turn daily signals into clearer next steps.",
      "",
      `${ctaLabel}: ${ctaUrl}`,
    ].join("\n")
    : draft.channel === "whatsapp"
      ? `${objective}\n\nVYVA helps make daily care clearer and easier to act on. ${ctaLabel}: ${ctaUrl}`
      : draft.channel === "tiktok"
        ? `${campaignName}\n\nHook: ${objective}\n\nShow the before: scattered care updates.\nShow the after: one clear VYVA next step.\n\nCTA: ${ctaLabel}.`
        : `${campaignName}\n\n${objective}\n\nAudience: ${audienceLabel}.\nChannel: ${channelName}.\nCTA: ${ctaLabel} - ${ctaUrl}`;

  return {
    title: `${campaignName} ${channelName} content`,
    channel: draft.channel,
    language: "en",
    status: "draft",
    subject: draft.channel === "email" ? campaignName : "",
    body,
    htmlBody: draft.channel === "email"
      ? `<h1>${campaignName}</h1><p>${objective.replace(/\n+/g, " ")}</p><p><a href="${ctaUrl}">${ctaLabel}</a></p>`
      : "",
    ctaLabel,
    ctaUrl,
    designJsonText: jsonText({
      generator: "marketing_campaign_planner",
      campaignName,
      audienceType: draft.audienceType,
      channel: draft.channel,
      objective,
      targetAudience: targetAudience ? audienceSnapshot(targetAudience) : null,
      scheduleStartsAt: draft.scheduleStartsAt || null,
      source: "campaign_planner_missing_content_action",
    }),
    mediaAssetsText: "[]",
  };
}

function contentDraftFromCampaignEditChannel(
  draft: CampaignEditDraft,
  channelDraft: CampaignChannelDraft,
  targetAudience: MarketingAudience | null,
): ContentDraft {
  const channels = campaignChannelsWithPrimary(draft);
  const contentAssetIds = Object.fromEntries(channels.map((item) => [item.channel, item.contentAssetId])) as Partial<Record<Channel, string>>;
  return contentDraftFromCampaignDraft({
    name: draft.name,
    audienceType: draft.audienceType,
    channel: channelDraft.channel,
    channels: channels.map((item) => item.channel),
    contentAssetId: channelDraft.contentAssetId,
    channelContentAssetIds: contentAssetIds,
    status: draft.status === "scheduled" ? "scheduled" : "draft",
    scheduleStartsAt: channelDraft.scheduledAt || draft.scheduleStartsAt,
    scheduleEndsAt: draft.scheduleEndsAt,
    objective: draft.objective,
    targetAudienceId: draft.targetAudienceId,
    recipientFilter: draft.recipientFilter,
    snapshotRecipients: false,
  }, targetAudience);
}

function templateGapStudioPlayId(channel: Channel, audienceType: Audience): CampaignStudioPlayId {
  if (audienceType === "b2b") {
    if (channel === "email") return "referral-partner-nurture";
    if (channel === "whatsapp" || channel === "facebook" || channel === "instagram") return "community-cohost";
    return "b2b-partner-outreach";
  }
  if (channel === "instagram") return "instagram-proof-point";
  if (channel === "tiktok") return "tiktok-myth-buster";
  if (channel === "facebook") return "local-event";
  if (channel === "linkedin") return "product-education";
  if (channel === "whatsapp") return "seasonal-check-in";
  return "profile-completion";
}

function templateGapToneId(channel: Channel, audienceType: Audience): CampaignStudioToneId {
  if (audienceType === "b2b" || channel === "linkedin") return "expert";
  if (channel === "instagram" || channel === "tiktok") return "uplifting";
  if (channel === "whatsapp") return "warm";
  return "direct";
}

function templateGapAngleId(channel: Channel, audienceType: Audience): CampaignStudioAngleId {
  if (audienceType === "b2b") return "proof";
  if (channel === "facebook" || channel === "instagram") return "local";
  if (channel === "whatsapp" || channel === "tiktok") return "action";
  return "balanced";
}

function templateGapSuggestionFor(channel: Channel, audienceType: Audience, existingCount: number, channelCount: number): ContentTemplateGapSuggestion {
  const audienceLabel = audienceType === "b2b" ? "B2B" : audienceType === "b2c" ? "B2C" : "Mixed";
  const channelName = channelLabel[channel];
  const coverageTarget = 3;
  const missingCount = Math.max(coverageTarget - existingCount, 0);
  const studioPlayId = templateGapStudioPlayId(channel, audienceType);
  const studioToneId = templateGapToneId(channel, audienceType);
  const studioAngleId = templateGapAngleId(channel, audienceType);
  const category = audienceType === "b2b"
    ? "B2B partner"
    : channel === "tiktok" || channel === "instagram"
      ? "Product education"
      : "Engagement";
  const subject = channel === "email" ? `${audienceLabel} VYVA update for {{first_name}}` : "";
  const ctaLabel = audienceType === "b2b" ? "Book a demo" : "Explore VYVA";
  const ctaUrl = audienceType === "b2b" ? "https://v2.vyva.life/demo" : "https://v2.vyva.life";
  const bodyLead = audienceType === "b2b"
    ? "Help care teams see the signal, not the noise."
    : "Make daily care feel clearer, calmer, and easier to act on.";
  const aiPrompt = [
    `Create ${missingCount || 1} attractive ${channelName} ${audienceLabel} marketing template${missingCount === 1 ? "" : "s"} for VYVA.`,
    `Use a ${campaignStudioToneLabel[studioToneId].toLowerCase()} tone and a ${campaignStudioAngleOptions.find((angle) => angle.id === studioAngleId)?.label.toLowerCase() ?? studioAngleId} angle.`,
    "Include one clear CTA, a plain-language benefit, and a version that can be adapted across channels.",
  ].join(" ");
  const body = channel === "whatsapp"
    ? `${bodyLead} VYVA turns check-ins, reminders, and care context into one practical next step. ${ctaLabel}: ${ctaUrl}`
    : channel === "tiktok"
      ? `${bodyLead}\n\nShow the before: scattered updates, missed context, uncertain next steps.\nShow the after: VYVA brings the care signal together so families and teams know what to do next.\n\nCTA: ${ctaLabel}.`
      : channel === "linkedin"
        ? `${bodyLead}\n\nVYVA connects daily signals, consent-aware communication, and care-team workflows so relationships can move from scattered messages to clear action.\n\n${ctaLabel}: ${ctaUrl}`
        : `${bodyLead}\n\nUse this starter to explain one problem, one VYVA capability, and one clear next action for ${audienceLabel} contacts.`;
  return {
    id: `gap-${channel}-${audienceType}`,
    title: `${channelName} ${audienceLabel} starter`,
    category,
    audienceType,
    channel,
    description: `Suggested because ${channelName} has ${channelCount} template${channelCount === 1 ? "" : "s"} and only ${existingCount} ${audienceLabel} fit${existingCount === 1 ? "" : "s"}.`,
    subject,
    body,
    htmlBody: channel === "email" ? `<h1>${bodyLead}</h1><p>Use this starter to explain one problem, one VYVA capability, and one clear next action.</p>` : "",
    ctaLabel,
    ctaUrl,
    designJson: {
      generator: "marketing_template_gap_suggestion",
      channel,
      audienceType,
      category,
      prompt: `${channelName} ${audienceLabel} campaign starter for VYVA communications.`,
      blocks: [
        { type: "problem", text: audienceType === "b2b" ? "Care teams need cleaner operational signals." : "Families need calmer care context." },
        { type: "solution", text: "VYVA turns daily signals into practical next steps." },
        { type: "cta", label: ctaLabel },
      ],
    },
    mediaAssets: [],
    existingCount,
    channelCount,
    coverageTarget,
    priorityLabel: existingCount === 0 ? "High priority" : existingCount === 1 ? "Medium priority" : "Fill next",
    aiPrompt,
    studioPlayId,
    studioToneId,
    studioAngleId,
  };
}

function templateGapSuggestionsFor(templates: ContentTemplate[]) {
  return CHANNELS.flatMap((channel) => {
    const channelCount = templates.filter((template) => template.channel === channel).length;
    return (["b2c", "b2b"] as Audience[]).map((audienceType) => {
      const existingCount = templates.filter((template) => (
        template.channel === channel
        && (template.audienceType === audienceType || template.audienceType === "both")
      )).length;
      return templateGapSuggestionFor(channel, audienceType, existingCount, channelCount);
    });
  })
    .filter((suggestion) => suggestion.existingCount < 3)
    .sort((a, b) => {
      if (a.existingCount !== b.existingCount) return a.existingCount - b.existingCount;
      if (a.channelCount !== b.channelCount) return a.channelCount - b.channelCount;
      if (a.audienceType !== b.audienceType) return a.audienceType === "b2c" ? -1 : 1;
      return channelLabel[a.channel].localeCompare(channelLabel[b.channel]);
    })
    .slice(0, 4);
}

function templateExpansionSuggestionsFor(templates: ContentTemplate[]) {
  return CHANNELS.flatMap((channel) => {
    const channelCount = templates.filter((template) => template.channel === channel).length;
    return (["b2c", "b2b"] as Audience[]).map((audienceType) => {
      const existingCount = templates.filter((template) => (
        template.channel === channel
        && (template.audienceType === audienceType || template.audienceType === "both")
      )).length;
      return templateGapSuggestionFor(channel, audienceType, existingCount, channelCount);
    });
  })
    .sort((a, b) => {
      if (a.existingCount !== b.existingCount) return a.existingCount - b.existingCount;
      if (a.channelCount !== b.channelCount) return a.channelCount - b.channelCount;
      if (a.audienceType !== b.audienceType) return a.audienceType === "b2c" ? -1 : 1;
      return channelLabel[a.channel].localeCompare(channelLabel[b.channel]);
    })
    .slice(0, TEMPLATE_GAP_BATCH_LIMIT);
}

function campaignDraftFromContentTemplate(template: ContentTemplate, targetAudience: MarketingAudience | null = null): CampaignDraft {
  return {
    name: `${template.title} campaign`,
    audienceType: template.audienceType,
    channel: template.channel,
    contentAssetId: "",
    status: "draft",
    scheduleStartsAt: "",
    scheduleEndsAt: "",
    objective: [
      template.description,
      "",
      `Audience: ${template.audienceType.toUpperCase()}.`,
      targetAudience ? `Audience/list: ${targetAudience.name}.` : "",
      `Primary channel: ${channelLabel[template.channel]}.`,
      template.ctaLabel ? `CTA: ${template.ctaLabel}${template.ctaUrl ? ` (${template.ctaUrl})` : ""}.` : "",
      "Next step: save the content draft, then attach the saved content asset to this campaign before sending.",
    ].filter(Boolean).join("\n"),
    targetAudienceId: targetAudience?.id ?? "",
    recipientFilter: targetAudience?.name ?? "",
    snapshotRecipients: Boolean(targetAudience?.mappedMemberCount || targetAudience?.memberCount),
  };
}

function campaignPlayForContentTemplate(template: ContentTemplate) {
  const haystack = lower([
    template.title,
    template.description,
    template.category,
    template.subject,
    template.body,
    template.ctaLabel,
  ].join(" "));
  return campaignStudioPlays.find((play) => (
    (play.audienceType === template.audienceType || play.audienceType === "both" || template.audienceType === "both")
    && (
      play.defaultChannel === template.channel
      || play.targetListHints.some((hint) => haystack.includes(lower(hint)))
      || haystack.includes(lower(play.label))
      || haystack.includes(lower(play.categoryId))
    )
  ))
    ?? campaignStudioPlays.find((play) => play.defaultChannel === template.channel)
    ?? campaignStudioPlays[0];
}

function campaignIntentBriefFromTemplate(
  template: ContentTemplate,
  play: CampaignStudioPlay,
  targetAudience: MarketingAudience | null,
  selectedChannels: Channel[],
) {
  const audienceLabel = targetAudience?.name ?? template.audienceType.toUpperCase();
  return [
    `Template campaign from "${template.title}".`,
    `Use case: ${template.description}`,
    `Playbook: ${play.label}.`,
    `Audience/list: ${audienceLabel}.`,
    `Channels: ${selectedChannels.map((channel) => channelLabel[channel]).join(" + ")}.`,
    template.subject ? `Starting hook: "${template.subject}".` : "",
    template.body ? `Starter copy: ${template.body}` : "",
    template.ctaLabel ? `CTA: ${template.ctaLabel}${template.ctaUrl ? ` (${template.ctaUrl})` : ""}.` : "",
    "AI direction: adapt this into a polished campaign pack with one clear promise, channel-specific copy, and no extra asks.",
    "Goal: create the saved content asset, attach it to the campaign, then publish or hand off through the selected route.",
  ].filter(Boolean).join("\n");
}

function campaignChannelDraftFromChannel(channel: CampaignChannel, fallbackStatus: CampaignStatus, fallbackSchedule: string): CampaignChannelDraft {
  return {
    id: channel.id || newDraftId(),
    channel: channel.channel,
    contentAssetId: channel.contentAssetId ?? "",
    status: normalizeCampaignStatus(channel.status || fallbackStatus),
    scheduledAt: toDateTimeLocal(channel.scheduledAt) || fallbackSchedule,
  };
}

function audienceReferencesFromRecord(value: unknown) {
  const record = recordValue(value);
  const refs: string[] = [];
  for (const key of ["targetAudienceId", "audienceId", "audienceListId", "listId", "lovableAudienceId", "audienceExternalId", "audience_external_id"]) {
    const item = record[key];
    if (typeof item === "string" && item.trim()) refs.push(item.trim());
  }
  for (const key of ["audienceExternalIds", "audience_external_ids", "audienceIds", "audience_ids", "audiences", "lists", "contactLists", "contact_lists"]) {
    const item = record[key];
    if (Array.isArray(item)) {
      refs.push(...item.map((entry) => typeof entry === "string" ? entry.trim() : "").filter(Boolean));
    }
  }
  for (const key of ["targetAudience", "audienceList", "audience", "list"]) {
    const nested = recordValue(record[key]);
    for (const nestedKey of ["id", "lovableExternalId", "lovable_external_id", "externalId", "external_id", "name"]) {
      const item = nested[nestedKey];
      if (typeof item === "string" && item.trim()) refs.push(item.trim());
    }
  }
  const list = record.list;
  if (typeof list === "string" && list.trim()) refs.push(list.trim());
  return Array.from(new Set(refs));
}

function campaignTargetAudience(campaign: Campaign, audiences: MarketingAudience[]) {
  const metadata = recordValue(campaign.metadata);
  const refs = [
    ...audienceReferencesFromRecord(metadata),
    ...audienceReferencesFromRecord(metadata.lovable),
    ...(campaign.recipients ?? []).flatMap((recipient) => audienceReferencesFromRecord(recipient.snapshot)),
  ];
  return audiences.find((audience) => refs.some((reference) => audienceMatchesReference(audience, reference))) ?? null;
}

function campaignRecipientConsentStatus(recipient: CampaignRecipient, contactByCampaignRecipientId?: ReadonlyMap<string, MarketingContact>) {
  const contact = contactByCampaignRecipientId?.get(recipient.id) ?? null;
  return contact?.consentStatus ?? String(recordValue(recipient.snapshot).consentStatus ?? "unknown");
}

function campaignEmailRecipientConsentReviewCount(campaign: Campaign, contactByCampaignRecipientId?: ReadonlyMap<string, MarketingContact>) {
  return (campaign.recipients ?? [])
    .filter((recipient) => recipient.channel === "email")
    .filter((recipient) => campaignRecipientConsentStatus(recipient, contactByCampaignRecipientId) !== "opted_in")
    .length;
}

function campaignRowReadiness(campaign: Campaign, contentById: ReadonlyMap<string, ContentAsset>, audiences: MarketingAudience[], contactByCampaignRecipientId?: ReadonlyMap<string, MarketingContact>): CampaignRowReadiness {
  const targetAudience = campaignTargetAudience(campaign, audiences);
  const channels = campaign.channels;
  const missingContentChannels = channels.filter((channel) => !channel.contentAssetId || !contentById.has(channel.contentAssetId));
  const emailChannels = channels.filter((channel) => channel.channel === "email");
  const hasEmailSendPath = emailChannels.some((channel) => Boolean(channel.contentAssetId && contentById.has(channel.contentAssetId)));
  const hasPlanningOnlyChannels = channels.some((channel) => channel.channel !== "email");
  const targetAudienceNeedsMapping = Boolean(targetAudience && targetAudience.memberCount > 0 && targetAudience.mappedMemberCount === 0);
  const needsSchedule = ["scheduled", "published"].includes(campaign.status) && !campaign.scheduleStartsAt;
  const needsRecipients = hasEmailSendPath && campaign.recipientCount <= 0;
  const emailRecipientConsentReviewCount = hasEmailSendPath
    ? campaignEmailRecipientConsentReviewCount(campaign, contactByCampaignRecipientId)
    : 0;
  const checks = [
    channels.length > 0,
    missingContentChannels.length === 0,
    !targetAudienceNeedsMapping,
    !needsSchedule,
    !needsRecipients,
    emailRecipientConsentReviewCount === 0,
  ];
  const readyCount = checks.filter(Boolean).length;
  const totalCount = checks.length;

  if (channels.length === 0) {
    return {
      state: "blocked",
      label: "No channels",
      detail: "Add at least one channel before this can move forward.",
      readyCount,
      totalCount,
    };
  }

  if (missingContentChannels.length > 0) {
    return {
      state: "blocked",
      label: "Needs content",
      detail: `Attach content for ${missingContentChannels.map((channel) => channelLabel[channel.channel]).join(", ")}.`,
      readyCount,
      totalCount,
    };
  }

  if (needsRecipients) {
    return {
      state: "blocked",
      label: "Snapshot recipients",
      detail: "Email has content, but no saved recipients yet.",
      readyCount,
      totalCount,
    };
  }

  if (emailRecipientConsentReviewCount > 0) {
    return {
      state: "needs_action",
      label: "Review consent",
      detail: `${emailRecipientConsentReviewCount} saved email recipient${emailRecipientConsentReviewCount === 1 ? "" : "s"} ${emailRecipientConsentReviewCount === 1 ? "needs" : "need"} opted-in consent before sending.`,
      readyCount,
      totalCount,
    };
  }

  if (targetAudienceNeedsMapping) {
    return {
      state: "needs_action",
      label: "Map audience",
      detail: `${targetAudience?.name ?? "Audience"} has no mapped contacts yet.`,
      readyCount,
      totalCount,
    };
  }

  if (needsSchedule) {
    return {
      state: "needs_action",
      label: "Add schedule",
      detail: "Scheduled or published campaigns need a start time.",
      readyCount,
      totalCount,
    };
  }

  if (hasEmailSendPath) {
    return {
      state: "ready",
      label: "Ready to send",
      detail: `${campaign.recipientCount} saved recipient${campaign.recipientCount === 1 ? "" : "s"} and email content linked.`,
      readyCount,
      totalCount,
    };
  }

  if (hasPlanningOnlyChannels) {
    return {
      state: "planning",
      label: "Manual handoff",
      detail: "Content is linked for planning/tracking channels.",
      readyCount,
      totalCount,
    };
  }

  return {
    state: "needs_action",
    label: "Review",
    detail: "Open details to finish campaign setup.",
    readyCount,
    totalCount,
  };
}

function campaignRowReadinessActionLabel(readiness: CampaignRowReadiness) {
  if (readiness.label === "Ready to send") return "Review send";
  if (readiness.label === "Snapshot recipients") return "Snapshot list";
  if (readiness.label === "Needs content") return "Attach content";
  if (readiness.label === "Review consent") return "Review consent";
  if (readiness.label === "Map audience") return "Map list";
  if (readiness.label === "Add schedule") return "Set time";
  if (readiness.label === "Manual handoff") return "Prepare handoff";
  if (readiness.label === "No channels") return "Add channel";
  return "Open setup";
}

function campaignMetadataWithTarget(existingMetadata: unknown, targetAudience: MarketingAudience | null) {
  const metadata = { ...recordValue(existingMetadata) };
  for (const key of ["targetAudience", "targetAudienceId", "audienceId", "audienceListId", "listId", "lovableAudienceId", "audienceExternalId", "audience_external_id", "audienceList"]) {
    delete metadata[key];
  }
  const targetAudienceSnapshot = audienceSnapshot(targetAudience);
  return targetAudienceSnapshot
    ? {
        ...metadata,
        targetAudienceId: targetAudience.id,
        audienceExternalId: targetAudience.lovableExternalId ?? targetAudience.id,
        targetAudience: targetAudienceSnapshot,
      }
    : metadata;
}

function normalizeManualPublishResultStatus(value: unknown): ManualPublishResultStatus {
  return value === "scheduled" || value === "blocked" || value === "needs_follow_up" ? value : "published";
}

function emptyManualPublishTrackerDraft(channel: Channel = "linkedin", scheduledAt = ""): ManualPublishTrackerDraft {
  return {
    channel,
    result: "published",
    url: "",
    notes: "",
    publishedAt: scheduledAt || toDateTimeLocal(new Date().toISOString()),
    audienceReached: "",
    engagements: "",
  };
}

function manualPublishResultsFromMetadata(metadata: unknown): ManualPublishResult[] {
  const results = recordValue(metadata).manualPublishResults;
  if (!Array.isArray(results)) return [];
  return results.flatMap((item) => {
    const record = recordValue(item);
    const channel = record.channel;
    const publishedAt = record.publishedAt;
    const recordedAt = record.recordedAt;
    if (!CHANNELS.includes(channel as Channel) || typeof publishedAt !== "string" || !publishedAt) return [];
    return [{
      channel: channel as Channel,
      result: normalizeManualPublishResultStatus(record.result),
      url: typeof record.url === "string" && record.url.trim() ? record.url.trim() : undefined,
      notes: typeof record.notes === "string" && record.notes.trim() ? record.notes.trim() : undefined,
      publishedAt,
      audienceReached: typeof record.audienceReached === "number" && Number.isFinite(record.audienceReached) ? record.audienceReached : undefined,
      engagements: typeof record.engagements === "number" && Number.isFinite(record.engagements) ? record.engagements : undefined,
      recordedAt: typeof recordedAt === "string" && recordedAt ? recordedAt : publishedAt,
    }];
  });
}

function manualPublishResultsFromMetadataText(value: string) {
  try {
    return manualPublishResultsFromMetadata(parseJsonText(value, "Campaign metadata"));
  } catch {
    return [];
  }
}

function summarizeManualPublishResults(results: ManualPublishResult[]): ManualPublishSummary {
  const datedResults = [...results].sort((a, b) => {
    const bTime = new Date(b.recordedAt || b.publishedAt).getTime();
    const aTime = new Date(a.recordedAt || a.publishedAt).getTime();
    return (Number.isFinite(bTime) ? bTime : 0) - (Number.isFinite(aTime) ? aTime : 0);
  });
  return {
    count: datedResults.length,
    latest: datedResults[0] ?? null,
    reached: datedResults.reduce((sum, result) => sum + (result.audienceReached ?? 0), 0),
    engagements: datedResults.reduce((sum, result) => sum + (result.engagements ?? 0), 0),
    followUps: datedResults.filter((result) => result.result === "needs_follow_up" || result.result === "blocked").length,
  };
}

function campaignMetadataWithManualPublishResult(existingMetadata: unknown, result: ManualPublishResult) {
  const metadata = { ...recordValue(existingMetadata) };
  const previousResults = manualPublishResultsFromMetadata(metadata);
  return {
    ...metadata,
    manualPublishResults: [result, ...previousResults].slice(0, 25),
    lastManualPublishResult: result,
  };
}

function optionalManualMetric(value: string, label: string) {
  const trimmed = value.trim();
  if (!trimmed) return undefined;
  const parsed = Number(trimmed);
  if (!Number.isFinite(parsed) || parsed < 0) {
    throw new Error(`${label} must be 0 or more.`);
  }
  return Math.round(parsed);
}

function isoDateTimeFromTracker(value: string) {
  if (!value) return new Date().toISOString();
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) throw new Error("Publish time must be a valid date.");
  return date.toISOString();
}

function emptyCampaignEditDraft(): CampaignEditDraft {
  return {
    name: "",
    audienceType: "b2c",
    channel: "email",
    contentAssetId: "",
    status: "draft",
    scheduleStartsAt: "",
    scheduleEndsAt: "",
    timezone: "Europe/Madrid",
    objective: "",
    targetAudienceId: "",
    source: "vyva",
    lovableExternalId: "",
    metadataText: "",
    recipientFilter: "",
    snapshotRecipients: false,
    channels: [newCampaignChannelDraft()],
  };
}

function campaignEditDraftFromCampaign(campaign: Campaign, audiences: MarketingAudience[] = []): CampaignEditDraft {
  const status = normalizeCampaignStatus(campaign.status);
  const scheduleStartsAt = toDateTimeLocal(campaign.scheduleStartsAt);
  const scheduleEndsAt = toDateTimeLocal(campaign.scheduleEndsAt);
  const channels = campaign.channels.length
    ? campaign.channels.map((channel) => campaignChannelDraftFromChannel(channel, status, scheduleStartsAt))
    : [newCampaignChannelDraft("email", status, scheduleStartsAt)];
  const primaryChannel = channels[0];
  const targetAudience = campaignTargetAudience(campaign, audiences);
  return {
    name: campaign.name,
    audienceType: campaign.audienceType,
    channel: primaryChannel.channel,
    contentAssetId: primaryChannel.contentAssetId,
    status,
    scheduleStartsAt,
    scheduleEndsAt,
    timezone: campaign.timezone || "Europe/Madrid",
    objective: campaign.objective,
    targetAudienceId: targetAudience?.id ?? "",
    source: campaign.source ?? "vyva",
    lovableExternalId: campaign.lovableExternalId ?? "",
    metadataText: jsonText(campaign.metadata),
    recipientFilter: "",
    snapshotRecipients: false,
    channels,
  };
}

function campaignChannelsWithPrimary(draft: CampaignEditDraft) {
  const first = draft.channels[0] ?? newCampaignChannelDraft(draft.channel, draft.status, draft.scheduleStartsAt);
  return [
    {
      ...first,
      channel: draft.channel,
      contentAssetId: first.contentAssetId || draft.contentAssetId,
      status: draft.status,
      scheduledAt: draft.scheduleStartsAt,
    },
    ...draft.channels.slice(1),
  ];
}

function campaignChannelsPayload(draft: CampaignEditDraft) {
  return campaignChannelsWithPrimary(draft).map((channel) => ({
    channel: channel.channel,
    contentAssetId: channel.channel === "email" ? channel.contentAssetId || null : channel.contentAssetId || null,
    status: channel.status,
    scheduledAt: fromDateTimeLocal(channel.scheduledAt || draft.scheduleStartsAt),
  }));
}

function campaignDuplicateName(name: string) {
  const trimmed = name.trim() || "Untitled campaign";
  return /^copy of /i.test(trimmed) ? `${trimmed} copy` : `Copy of ${trimmed}`;
}

function campaignDuplicateMetadata(campaign: Campaign) {
  const metadata = { ...recordValue(campaign.metadata) };
  delete metadata.manualPublishResults;
  delete metadata.lastManualPublishResult;
  return {
    ...metadata,
    duplicatedFrom: {
      campaignId: campaign.id,
      name: campaign.name,
      source: campaign.source,
      lovableExternalId: campaign.lovableExternalId ?? null,
      duplicatedAt: new Date().toISOString(),
    },
  };
}

function campaignChannelsMatch(draft: CampaignEditDraft, campaign: Campaign) {
  const drafted = campaignChannelsPayload(draft);
  if (drafted.length !== campaign.channels.length) return false;
  return drafted.every((channel, index) => {
    const saved = campaign.channels[index];
    if (!saved) return false;
    return channel.channel === saved.channel
      && (channel.contentAssetId ?? "") === (saved.contentAssetId ?? "")
      && channel.status === normalizeCampaignStatus(saved.status)
      && toDateTimeLocal(channel.scheduledAt) === toDateTimeLocal(saved.scheduledAt);
  });
}

function notesFromMetadata(value: unknown) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return "";
  const notes = (value as Record<string, unknown>).notes;
  return typeof notes === "string" ? notes : "";
}

function translationFieldText(record: Record<string, unknown>, keys: string[]) {
  for (const key of keys) {
    const text = displayText(record[key]);
    if (text) return text;
  }
  return "";
}

function journeyStepTranslationDraft(language: string, value: unknown): JourneyStepTranslationDraft {
  if (typeof value === "string") {
    return { language, title: "", subject: "", body: value, ctaLabel: "", ctaUrl: "" };
  }
  const record = recordValue(value);
  return {
    language,
    title: translationFieldText(record, ["title", "name", "label", "templateTitle", "sequenceTitle"]),
    subject: translationFieldText(record, ["subject", "headline", "heading"]),
    body: translationFieldText(record, ["body", "text", "message", "caption", "copy", "content"]),
    ctaLabel: translationFieldText(record, ["ctaLabel", "cta_label", "buttonLabel", "button_label"]),
    ctaUrl: translationFieldText(record, ["ctaUrl", "cta_url", "buttonUrl", "button_url", "url"]),
  };
}

function journeyStepTranslationsFromConfigText(configText: string): JourneyStepTranslationDraft[] {
  const config = optionalJsonRecordText(configText);
  const translations = config.translations;
  if (Array.isArray(translations)) {
    return translations
      .map((item) => {
        const record = recordValue(item);
        const language = translationFieldText(record, ["language", "lang", "locale", "code"]);
        return language ? journeyStepTranslationDraft(language, record) : null;
      })
      .filter((item): item is JourneyStepTranslationDraft => Boolean(item));
  }
  return Object.entries(recordValue(translations))
    .map(([language, value]) => journeyStepTranslationDraft(language, value))
    .filter((item) => item.language);
}

function journeyStepDefaultLanguage(configText: string) {
  const config = optionalJsonRecordText(configText);
  return translationFieldText(config, ["default_language", "defaultLanguage", "language", "locale"])
    || journeyStepTranslationsFromConfigText(configText)[0]?.language
    || "";
}

function emptyJourneyEditDraft(): JourneyEditDraft {
  return {
    name: "",
    audienceType: "b2c",
    status: "draft",
    objective: "",
    targetAudienceId: "",
    source: "vyva",
    lovableExternalId: "",
    metadataText: "",
    triggerType: "",
    triggerConfigText: "",
    goalType: "",
    goalConfigText: "",
    exitOnGoal: true,
    steps: [],
  };
}

function journeyStepDraftFromStep(step: JourneyStep): JourneyStepDraft {
  return {
    id: step.id || newDraftId(),
    channel: step.channel,
    contentAssetId: step.contentAssetId ?? "",
    delayHours: String(Math.max(0, step.delayHours ?? 0)),
    kind: step.kind || "message",
    templateKind: step.templateKind ?? "",
    templateRef: step.templateRef ?? "",
    status: normalizeJourneyStatus(step.status),
    configText: jsonText(step.config),
    notes: notesFromMetadata(step.metadata),
  };
}

function journeyAudienceReferenceFromConfig(value: unknown) {
  const config = recordValue(value);
  for (const key of ["targetAudienceId", "audienceId", "audienceListId", "listId", "lovableAudienceId", "audienceExternalId", "audience_external_id"]) {
    const item = config[key];
    if (typeof item === "string" && item.trim()) return item.trim();
  }
  const audienceList = recordValue(config.audienceList ?? config.audience ?? config.list);
  for (const key of ["id", "lovableExternalId", "lovable_external_id", "externalId", "external_id", "name"]) {
    const item = audienceList[key];
    if (typeof item === "string" && item.trim()) return item.trim();
  }
  const list = config.list;
  return typeof list === "string" && list.trim() ? list.trim() : "";
}

function audienceMatchesReference(audience: MarketingAudience, reference: string) {
  const normalized = lower(reference);
  return Boolean(normalized) && [audience.id, audience.name, audience.lovableExternalId ?? ""].some((item) => lower(item) === normalized);
}

function journeyTargetAudience(journey: Pick<Journey, "triggerConfig">, audiences: MarketingAudience[]) {
  const reference = journeyAudienceReferenceFromConfig(journey.triggerConfig);
  if (!reference) return null;
  return audiences.find((audience) => audienceMatchesReference(audience, reference)) ?? null;
}

function stripJourneyAudienceSelection(config: Record<string, unknown>) {
  const next = { ...config };
  for (const key of ["targetAudienceId", "audienceId", "audienceListId", "listId", "lovableAudienceId", "audienceExternalId", "audience_external_id", "audienceList"]) {
    delete next[key];
  }
  return next;
}

function journeyEditDraftFromJourney(journey: Journey, audiences: MarketingAudience[] = []): JourneyEditDraft {
  const targetAudience = journeyTargetAudience(journey, audiences);
  return {
    name: journey.name,
    audienceType: journey.audienceType,
    status: normalizeJourneyStatus(journey.status),
    objective: journey.objective,
    targetAudienceId: targetAudience?.id ?? "",
    source: journey.source ?? "vyva",
    lovableExternalId: journey.lovableExternalId ?? "",
    metadataText: jsonText(journey.metadata),
    triggerType: journey.triggerType ?? "",
    triggerConfigText: jsonText(journey.triggerConfig),
    goalType: journey.goalType ?? "",
    goalConfigText: jsonText(journey.goalConfig),
    exitOnGoal: journey.exitOnGoal,
    steps: journey.steps.map(journeyStepDraftFromStep),
  };
}

function newJourneyStepDraft(channel: Channel = "email"): JourneyStepDraft {
  return {
    id: newDraftId(),
    channel,
    contentAssetId: "",
    delayHours: "0",
    kind: "message",
    templateKind: "",
    templateRef: "",
    status: "draft",
    configText: "",
    notes: "",
  };
}

function journeyStarterStepDraft({
  channel,
  contentAsset,
  delayHours,
  notes,
  config = {},
  kind = "message",
  status = "draft",
  templateKind,
  templateRef,
}: {
  channel: Channel;
  contentAsset: ContentAsset | null;
  delayHours: number;
  notes: string;
  config?: Record<string, unknown>;
  kind?: string;
  status?: JourneyStatus;
  templateKind?: string;
  templateRef?: string;
}): JourneyStepDraft {
  return {
    id: newDraftId(),
    channel,
    contentAssetId: contentAsset?.id ?? "",
    delayHours: String(Math.max(0, delayHours)),
    kind,
    templateKind: templateKind ?? (contentAsset ? "content_asset" : ""),
    templateRef: templateRef ?? contentAsset?.lovableExternalId ?? contentAsset?.id ?? "",
    status,
    configText: jsonText(config),
    notes,
  };
}

function parseJsonText(value: string, label: string) {
  const trimmed = value.trim();
  if (!trimmed) return {};
  try {
    const parsed = JSON.parse(trimmed);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error();
    return parsed as Record<string, unknown>;
  } catch {
    throw new Error(`${label} must be valid JSON.`);
  }
}

function parseJsonArrayText(value: string, label: string) {
  const trimmed = value.trim();
  if (!trimmed) return [];
  try {
    const parsed = JSON.parse(trimmed);
    if (!Array.isArray(parsed)) throw new Error();
    return parsed as unknown[];
  } catch {
    throw new Error(`${label} must be a valid JSON array.`);
  }
}

function optionalJsonRecordText(value: string) {
  const trimmed = value.trim();
  if (!trimmed) return {};
  try {
    const parsed = JSON.parse(trimmed);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as Record<string, unknown> : {};
  } catch {
    return {};
  }
}

function contentCreatePayloadFromDraft(draft: ContentDraft) {
  return {
    title: draft.title,
    channel: draft.channel,
    language: draft.language.trim() || "en",
    status: draft.status,
    subject: draft.subject || null,
    body: draft.body,
    htmlBody: draft.htmlBody.trim() || null,
    ctaLabel: draft.ctaLabel.trim() || null,
    ctaUrl: draft.ctaUrl.trim() || null,
    designJson: parseJsonText(draft.designJsonText, "Design JSON"),
    mediaAssets: parseJsonArrayText(draft.mediaAssetsText, "Media assets"),
  };
}

function nonNegativeInt(value: string, fallback = 0) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(0, Math.round(parsed));
}

function contentEditDraftFromContent(content: ContentAsset): ContentEditDraft {
  return {
    title: content.title,
    channel: content.channel,
    language: content.language || "en",
    status: normalizeContentStatus(content.status),
    subject: content.subject ?? "",
    body: content.body,
    htmlBody: content.htmlBody ?? "",
    ctaLabel: content.ctaLabel ?? "",
    ctaUrl: content.ctaUrl ?? "",
    source: content.source ?? "vyva",
    lovableExternalId: content.lovableExternalId ?? "",
    designJsonText: jsonText(content.designJson),
    mediaAssetsText: jsonArrayText(content.mediaAssets),
    metadataText: jsonText(content.metadata),
  };
}

function missingLovableReferenceRepairDraft(content: ContentAsset): ContentEditDraft {
  const base = contentEditDraftFromContent(content);
  const metadata = recordValue(content.metadata);
  const lovableMetadata = recordValue(metadata.lovable);
  const sourceReference = content.lovableExternalId
    || displayText(metadata.contentExternalId)
    || displayText(lovableMetadata.contentExternalId)
    || displayText(lovableMetadata.templateRef)
    || content.id;
  const title = base.title.trim() || "Missing Source content";
  const channelName = channelLabel[base.channel] ?? base.channel;
  const campaignName = displayText(lovableMetadata.campaignName) || displayText(metadata.campaignName);
  const journeyName = displayText(lovableMetadata.journeyName) || displayText(metadata.journeyName);
  const contextLine = campaignName
    ? `This draft replaces a missing Source asset referenced by "${campaignName}".`
    : journeyName
      ? `This draft replaces a missing Source asset referenced by "${journeyName}".`
      : "This draft replaces a Source/Lovable content reference that arrived without body or design data.";
  const reviewLine = `Original reference: ${sourceReference}. Review tone, offer, audience, and compliance before saving.`;
  const generatedBody = [
    `Draft replacement for ${title}`,
    "",
    contextLine,
    `Channel: ${channelName}.`,
    "",
    "Suggested message:",
    "Keep this communication focused on one useful next step for the audience. Make the benefit concrete, friendly, and easy to act on.",
    "",
    reviewLine,
  ].join("\n");
  const generatedHtml = [
    '<section style="font-family: Arial, sans-serif; max-width: 640px; margin: 0 auto; color: #241133;">',
    `  <p style="font-size: 12px; text-transform: uppercase; letter-spacing: 0.12em; color: #6f2dbd; font-weight: 700;">${escapeHtmlText(channelName)} replacement draft</p>`,
    `  <h1 style="font-size: 28px; line-height: 1.2; margin: 0 0 12px;">${escapeHtmlText(title)}</h1>`,
    `  <p style="font-size: 16px; line-height: 1.6;">${escapeHtmlText(contextLine)}</p>`,
    '  <p style="font-size: 16px; line-height: 1.6;">Keep the copy useful, specific, and easy to act on. Replace this placeholder with the final offer before publishing.</p>',
    `  <p style="font-size: 13px; line-height: 1.5; color: #7d6b65;">${escapeHtmlText(reviewLine)}</p>`,
    "</section>",
  ].join("\n");
  const generatedDesign = {
    ...recordValue(content.designJson),
    generator: "marketing_missing_lovable_reference_repair",
    sourceReference,
    channel: base.channel,
    title,
    reviewRequired: true,
    blocks: [
      { type: "eyebrow", text: `${channelName} replacement draft` },
      { type: "headline", text: title },
      { type: "body", text: contextLine },
      { type: "body", text: "Replace this placeholder with final copy, visual direction, and CTA before publishing." },
    ],
  };
  return {
    ...base,
    title,
    status: "draft",
    subject: base.subject.trim() || `${title}: ready for review`,
    body: base.body.trim() ? base.body : generatedBody,
    htmlBody: base.htmlBody.trim() ? base.htmlBody : generatedHtml,
    ctaLabel: base.ctaLabel.trim() || "Review in VYVA",
    ctaUrl: base.ctaUrl.trim() || "https://v2.vyva.life",
    designJsonText: jsonText(generatedDesign),
    metadataText: jsonText({
      ...metadata,
      lovable_source_type: "source_repaired_draft",
      original_lovable_source_type: metadataString(content.metadata, "lovable_source_type") || "missing_lovable_reference",
      repairDraft: {
        generator: "marketing_missing_lovable_reference_repair",
        generatedAt: new Date().toISOString(),
        originalLovableExternalId: content.lovableExternalId ?? null,
        sourceReference,
        reviewRequired: true,
      },
    }),
  };
}

