function journeyPayloadFromDraft(draft: JourneyEditDraft, targetAudience: MarketingAudience | null = null) {
  const triggerConfig = stripJourneyAudienceSelection(parseJsonText(draft.triggerConfigText, "Trigger config"));
  const targetAudienceSnapshot = audienceSnapshot(targetAudience);
  return {
    name: draft.name.trim(),
    audienceType: draft.audienceType,
    status: draft.status,
    objective: draft.objective,
    source: draft.source.trim() || "vyva",
    lovableExternalId: draft.lovableExternalId.trim() || null,
    metadata: parseJsonText(draft.metadataText, "Journey metadata"),
    triggerType: draft.triggerType.trim() || null,
    triggerConfig: targetAudienceSnapshot
      ? {
          ...triggerConfig,
          targetAudienceId: targetAudience.id,
          audienceExternalId: targetAudience.lovableExternalId ?? targetAudience.id,
          audienceList: targetAudienceSnapshot,
        }
      : triggerConfig,
    goalType: draft.goalType.trim() || null,
    goalConfig: parseJsonText(draft.goalConfigText, "Goal config"),
    exitOnGoal: draft.exitOnGoal,
    steps: draft.steps.map((step, index) => {
      const delayHours = nonNegativeInt(step.delayHours);
      return {
        stepOrder: index,
        channel: step.channel,
        contentAssetId: step.contentAssetId || null,
        delayHours,
        dayOffset: Math.floor(delayHours / 24),
        kind: step.kind.trim() || "message",
        templateKind: step.templateKind.trim() || null,
        templateRef: step.templateRef.trim() || null,
        status: step.status,
        config: parseJsonText(step.configText, `Step ${index + 1} config`),
        metadata: step.notes.trim() ? { notes: step.notes.trim() } : {},
      };
    }),
  };
}

function toDateTimeLocal(value: string | null) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60_000);
  return local.toISOString().slice(0, 16);
}

function fromDateTimeLocal(value: string) {
  return value ? new Date(value).toISOString() : null;
}

function campaignAllowsContact(campaignAudience: Audience, contactAudience: Audience) {
  return campaignAudience === "both" || contactAudience === "both" || contactAudience === campaignAudience;
}

function recipientForChannel(contact: MarketingContact, channel: Channel) {
  if (channel === "email") return contact.email;
  if (channel === "whatsapp") return contact.whatsappNumber || contact.phoneNumber;
  return contact.email || contact.whatsappNumber || contact.phoneNumber || contact.id;
}

function contactReachableForChannel(contact: MarketingContact, channel: Channel) {
  if (channel === "email" || channel === "whatsapp") return Boolean(recipientForChannel(contact, channel));
  const availability = contact.channelAvailability;
  if (availability && Object.keys(availability).length > 0) {
    const value = availability[channel];
    return value === true || value === "true" || value === 1 || value === "1";
  }
  return Boolean(recipientForChannel(contact, channel));
}

function recipientSnapshot(contact: MarketingContact) {
  return {
    fullName: contact.fullName,
    email: contact.email,
    phoneNumber: contact.phoneNumber,
    whatsappNumber: contact.whatsappNumber,
    audienceType: contact.audienceType,
    companyName: contact.companyName,
    roleLabel: contact.roleLabel,
    consentStatus: contact.consentStatus,
    tags: contact.tags,
    lists: contact.lists,
  };
}

function contactMatchesAudienceList(contact: MarketingContact, audience: MarketingAudience | null) {
  if (!audience) return true;
  const contactExternalId = lower(contact.lovableExternalId);
  const externalIds = new Set(audience.contactExternalIds.map((id) => lower(id)));
  return Boolean(contactExternalId && externalIds.has(contactExternalId))
    || contact.lists.some((list) => lower(list) === lower(audience.name));
}

function audienceSnapshot(audience: MarketingAudience | null) {
  if (!audience) return null;
  return {
    id: audience.id,
    name: audience.name,
    listType: audience.listType,
    source: audience.source,
    lovableExternalId: audience.lovableExternalId,
    memberCount: audience.memberCount,
    mappedMemberCount: audience.mappedMemberCount,
  };
}

function campaignStudioDefaultSchedule(play: CampaignStudioPlay) {
  const date = new Date();
  date.setDate(date.getDate() + play.scheduleDaysFromNow);
  date.setHours(10, 0, 0, 0);
  return toDateTimeLocal(date.toISOString());
}

function templatePackAudience(pack: ContentTemplatePack, heroTemplate: ContentTemplate | null, play: CampaignStudioPlay): Audience {
  if (heroTemplate?.audienceType && heroTemplate.audienceType !== "both") return heroTemplate.audienceType;
  if (play.audienceType && play.audienceType !== "both") return play.audienceType;
  if (pack.id.includes("partner")) return "b2b";
  if (pack.id.includes("family") || pack.id.includes("caregiver")) return "b2c";
  return "both";
}

function templatePackTriggerType(pack: ContentTemplatePack) {
  if (pack.id === "family-onboarding") return "signup_or_invite_sent";
  if (pack.id === "partner-growth") return "list_joined";
  if (pack.id === "local-community") return "event_interest";
  if (pack.id === "local-event-relationship") return "local_event_discovered";
  if (pack.id === "local-event-operations") return "event_scheduled";
  if (pack.id === "retention-feedback") return "inactive_30_days";
  if (pack.id === "care-confidence-reactivation") return "inactive_or_incomplete_profile";
  if (pack.id === "social-launch") return "campaign_launch";
  return "manual_add";
}

function templatePackGoalType(pack: ContentTemplatePack) {
  if (pack.id === "family-onboarding") return "profile_completed";
  if (pack.id === "partner-growth") return "reply";
  if (pack.id === "local-community") return "event_response";
  if (pack.id === "local-event-relationship") return "event_rsvp_or_followup";
  if (pack.id === "local-event-operations") return "event_follow_up_completed";
  if (pack.id === "retention-feedback") return "feedback_or_reply";
  if (pack.id === "care-confidence-reactivation") return "care_routine_restarted";
  if (pack.id === "social-launch") return "engagement";
  return "reviewed";
}

function templateSequenceDelayHours(offset: string, index: number) {
  const dayMatch = offset.match(/day\s*(-?\d+)/i);
  if (dayMatch) return Math.max(0, Number(dayMatch[1]) * 24);
  const weekMatch = offset.match(/week\s*(-?\d+)/i);
  if (weekMatch) return Math.max(0, Number(weekMatch[1]) * 7 * 24);
  return index * 48;
}

function scheduleDateTimeLocal(daysFromNow: number, hour: number) {
  const date = new Date();
  date.setDate(date.getDate() + Math.max(0, daysFromNow));
  date.setHours(hour, 0, 0, 0);
  return toDateTimeLocal(date.toISOString());
}

function campaignStudioScheduleSuggestions(
  play: CampaignStudioPlay,
  selectedChannels: Channel[],
  audience: MarketingAudience | null,
): CampaignStudioScheduleSuggestion[] {
  const channels = normalizeCampaignStudioChannels(play.defaultChannel, selectedChannels);
  const hasSocial = channels.some((channel) => ["facebook", "instagram", "linkedin", "tiktok"].includes(channel));
  const hasWhatsApp = channels.includes("whatsapp");
  const hasEmail = channels.includes("email");
  const audienceText = lower(`${audience?.name ?? ""} ${audience?.description ?? ""} ${audience?.listType ?? ""}`);
  const partnerAudience = play.audienceType === "b2b" || audienceText.includes("partner") || audienceText.includes("provider");
  const primaryHour = partnerAudience ? 9 : hasWhatsApp ? 11 : 10;
  const relationshipHour = partnerAudience ? 15 : 18;
  const socialHour = hasSocial ? 19 : hasEmail ? 10 : 12;

  return [
    {
      id: "primary",
      label: partnerAudience ? "Partner morning" : hasWhatsApp ? "WhatsApp late morning" : "Email morning",
      value: scheduleDateTimeLocal(play.scheduleDaysFromNow, primaryHour),
      detail: partnerAudience
        ? "Good for B2B inboxes before the day gets noisy."
        : hasWhatsApp
          ? "Useful for short practical nudges after the morning rush."
          : "A reliable default for email opens and review.",
      reason: `${channelLabel[channels[0] ?? play.defaultChannel]} primary window`,
    },
    {
      id: "relationship",
      label: partnerAudience ? "Follow-up afternoon" : "Family evening",
      value: scheduleDateTimeLocal(play.scheduleDaysFromNow + 1, relationshipHour),
      detail: partnerAudience
        ? "A second slot for partner follow-up, demos, and LinkedIn review."
        : "Better for caregivers and family members checking messages after work.",
      reason: partnerAudience ? "B2B response window" : "Caregiver attention window",
    },
    {
      id: "social",
      label: hasSocial ? "Social prime slot" : "Reminder slot",
      value: scheduleDateTimeLocal(play.scheduleDaysFromNow + 2, socialHour),
      detail: hasSocial
        ? "Use for Facebook, Instagram, LinkedIn, or TikTok manual publishing."
        : "A backup schedule for a follow-up or unsent planning draft.",
      reason: hasSocial ? "Social publishing window" : "Fallback timing",
    },
  ];
}

function uniqueChannels(values: Channel[]) {
  return Array.from(new Set(values.filter((value): value is Channel => CHANNELS.includes(value))));
}

function recommendedCampaignStudioChannels(play: CampaignStudioPlay) {
  const channelsByCategory: Record<Exclude<CampaignStudioCategoryId, "all">, Channel[]> = {
    onboarding: ["email", "whatsapp"],
    engagement: ["email", "whatsapp"],
    education: ["email", "facebook"],
    partner: ["email", "linkedin"],
    community: ["email", "facebook", "instagram"],
    social: [play.defaultChannel, "email"],
    retention: ["email", "whatsapp"],
  };
  return uniqueChannels([play.defaultChannel, ...(channelsByCategory[play.categoryId] ?? [])]);
}

function normalizeCampaignStudioChannels(primary: Channel, selected: Channel[]) {
  const normalized = uniqueChannels([primary, ...selected]);
  return normalized.length ? normalized : [primary];
}

function bestCampaignStudioAudience(play: CampaignStudioPlay, audiences: MarketingAudience[]) {
  const hints = play.targetListHints.map((hint) => lower(hint));
  return audiences.find((audience) => {
    const haystack = lower(`${audience.name} ${audience.description ?? ""} ${audience.listType} ${audience.source} ${audience.lovableExternalId ?? ""}`);
    return hints.some((hint) => hint && haystack.includes(hint));
  }) ?? audiences.find((audience) => audience.memberCount > 0) ?? null;
}

function campaignIntentHasAny(text: string, words: string[]) {
  return words.some((word) => text.includes(word));
}

function campaignStudioPlayById(id: CampaignStudioPlayId) {
  return campaignStudioPlays.find((play) => play.id === id) ?? campaignStudioPlays[0];
}

function campaignIntentPlay(brief: string) {
  const text = lower(brief);
  if (campaignIntentHasAny(text, ["monthly", "newsletter", "digest", "roundup", "report", "summary"])) return campaignStudioPlayById("monthly-care-digest");
  if (campaignIntentHasAny(text, ["webinar", "session", "demo", "professional session"])) return campaignStudioPlayById("partner-webinar");
  if (
    campaignIntentHasAny(text, ["discharge", "hospital", "rehab", "care transition", "transition support", "post-discharge", "post discharge", "care change"])
    || (campaignIntentHasAny(text, ["first 72 hours", "72 hours"]) && campaignIntentHasAny(text, ["follow-up", "follow up", "provider", "family"]))
  ) return campaignStudioPlayById("care-transition-support");
  if (
    campaignIntentHasAny(text, ["clinic referral", "pharmacy referral", "referral pathway", "referral path", "clinic", "pharmacy"])
    || (campaignIntentHasAny(text, ["provider", "referral", "refer"]) && campaignIntentHasAny(text, ["handoff", "pathway", "path", "clinic", "pharmacy", "post visit", "post-visit"]))
  ) return campaignStudioPlayById("clinic-referral");
  if (
    campaignIntentHasAny(text, ["family referral", "caregiver referral", "ambassador", "word of mouth", "invite a friend", "share with a friend", "refer a family", "warm introduction", "warm intro", "referral card"])
    || (campaignIntentHasAny(text, ["happy", "satisfied", "warm", "trust"]) && campaignIntentHasAny(text, ["referral", "refer", "share", "introduction", "intro"]))
  ) return campaignStudioPlayById("family-referral-ambassador");
  if (
    campaignIntentHasAny(text, ["seasonal", "heatwave", "heat wave", "hot weather", "winter", "cold weather", "holiday", "holidays", "weather", "summer", "autumn", "fall", "spring"])
    || (campaignIntentHasAny(text, ["hydration", "warmth", "travel", "transport"]) && campaignIntentHasAny(text, ["check-in", "check in", "care details", "profile", "support owner"]))
  ) return campaignStudioPlayById("seasonal-check-in");
  if (
    campaignIntentHasAny(text, ["event", "activity", "workshop", "community", "madrid", "barcelona", "valencia", "local", "venue", "host", "rsvp"])
    || (campaignIntentHasAny(text, ["neighbourhood", "neighborhood", "postcode", "postal code", "area"]) && campaignIntentHasAny(text, ["run sheet", "operations", "attendance", "follow-up", "follow up"]))
  ) return campaignStudioPlayById("local-event");
  if (campaignIntentHasAny(text, ["referral", "refer", "provider", "partner follow", "partner nurture"])) return campaignStudioPlayById("referral-partner-nurture");
  if (campaignIntentHasAny(text, ["partner", "b2b", "care home", "clinic", "pharmacy", "provider"])) return campaignStudioPlayById("b2b-partner-outreach");
  if (campaignIntentHasAny(text, ["inactive", "quiet", "winback", "win back", "reactivate", "reactivation"])) return campaignStudioPlayById("reactivation");
  if (campaignIntentHasAny(text, ["medication", "medicine", "pill"])) return campaignStudioPlayById("medication-routine-education");
  if (
    campaignIntentHasAny(text, ["activation", "activate", "daily signal", "daily routine", "first useful", "first action", "routine activation", "update route"])
    || (campaignIntentHasAny(text, ["routine"]) && campaignIntentHasAny(text, ["profile", "signup", "new user", "new users", "daily", "contact", "care circle"]))
  ) return campaignStudioPlayById("routine-activation");
  if (campaignIntentHasAny(text, ["caregiver", "family", "invite", "welcome", "onboard", "onboarding"])) return campaignStudioPlayById("caregiver-onboarding");
  if (campaignIntentHasAny(text, ["profile", "complete", "setup", "account"])) return campaignStudioPlayById("profile-completion");
  if (campaignIntentHasAny(text, ["feedback", "survey", "questionnaire"])) return campaignStudioPlayById("feedback-survey");
  if (campaignIntentHasAny(text, ["instagram", "visual", "story", "reel"])) return campaignStudioPlayById("instagram-proof-point");
  if (campaignIntentHasAny(text, ["tiktok", "short video", "myth"])) return campaignStudioPlayById("tiktok-myth-buster");
  return campaignStudioPlayById("product-education");
}

function campaignIntentChannels(brief: string, play: CampaignStudioPlay) {
  const text = lower(brief);
  const channels: Channel[] = [];
  if (campaignIntentHasAny(text, ["email", "newsletter"])) channels.push("email");
  if (campaignIntentHasAny(text, ["whatsapp", "whats app"])) channels.push("whatsapp");
  if (campaignIntentHasAny(text, ["sms", "text message", "text reminder"])) channels.push("sms");
  if (campaignIntentHasAny(text, ["phone", "call", "call script", "phone call"])) channels.push("phone");
  if (campaignIntentHasAny(text, ["print", "flyer", "direct mail", "one-page", "one page", "handoff sheet"])) channels.push("print");
  if (campaignIntentHasAny(text, ["event", "workshop", "venue", "rsvp"])) channels.push("event");
  if (campaignIntentHasAny(text, ["facebook", "fb"])) channels.push("facebook");
  if (campaignIntentHasAny(text, ["instagram", "insta", "reel", "story"])) channels.push("instagram");
  if (campaignIntentHasAny(text, ["linkedin", "linked in"])) channels.push("linkedin");
  if (campaignIntentHasAny(text, ["tiktok", "short video"])) channels.push("tiktok");
  return channels.length ? uniqueChannels(channels) : recommendedCampaignStudioChannels(play);
}

function campaignIntentTone(brief: string, play: CampaignStudioPlay): CampaignStudioToneId {
  const text = lower(brief);
  if (campaignIntentHasAny(text, ["partner", "provider", "professional", "expert", "b2b", "demo", "webinar"]) || play.audienceType === "b2b") return "expert";
  if (campaignIntentHasAny(text, ["urgent", "direct", "clear", "quick", "now"])) return "direct";
  if (campaignIntentHasAny(text, ["inspiring", "positive", "community", "celebrate", "social", "story"])) return "uplifting";
  return "warm";
}

function campaignIntentAngle(brief: string): CampaignStudioAngleId {
  const text = lower(brief);
  if (campaignIntentHasAny(text, ["proof", "result", "case", "evidence", "trust", "credibility"])) return "proof";
  if (campaignIntentHasAny(text, ["local", "madrid", "barcelona", "valencia", "community", "nearby"])) return "local";
  if (campaignIntentHasAny(text, ["join", "book", "reserve", "start", "signup", "sign up", "register", "invite"])) return "action";
  return "balanced";
}

function campaignIntentAudience(brief: string, play: CampaignStudioPlay, audiences: MarketingAudience[]) {
  const text = lower(brief);
  const tokens = Array.from(new Set(text.split(/[^a-z0-9]+/).filter((token) => token.length >= 3)));
  const scored = audiences
    .map((audience) => {
      const haystack = lower([
        audience.name,
        audience.description ?? "",
        audience.listType,
        audience.source,
        audience.lovableExternalId ?? "",
        jsonText(audience.rules),
      ].join(" "));
      let score = 0;
      if (audience.memberCount > 0) score += 1;
      if (play.audienceType !== "both" && haystack.includes(play.audienceType)) score += 2;
      for (const hint of play.targetListHints) {
        if (haystack.includes(lower(hint))) score += 3;
      }
      for (const token of tokens) {
        if (haystack.includes(token)) score += 1;
      }
      if (text.includes(lower(audience.name))) score += 6;
      return { audience, score };
    })
    .sort((a, b) => b.score - a.score || b.audience.mappedMemberCount - a.audience.mappedMemberCount);

  return scored[0]?.score ? scored[0].audience : bestCampaignStudioAudience(play, audiences);
}

function campaignIntentMatch(brief: string, audiences: MarketingAudience[]): CampaignIntentMatch {
  const play = campaignIntentPlay(brief);
  const channels = campaignIntentChannels(brief, play);
  const toneId = campaignIntentTone(brief, play);
  const angleId = campaignIntentAngle(brief);
  const targetAudience = campaignIntentAudience(brief, play, audiences);
  return {
    play,
    channels,
    toneId,
    angleId,
    targetAudience,
    reasons: [
      `${play.label} play`,
      targetAudience ? `${targetAudience.name} list` : "best matching list",
      `${channels.map((channel) => channelLabel[channel]).join(" + ")} channels`,
      `${campaignStudioToneLabel[toneId]} tone`,
    ],
  };
}

function contentMatchesCampaignPlay(play: CampaignStudioPlay, channel: Channel, item: ContentAsset) {
  if (item.channel !== channel || item.status === "archived") return false;
  const haystack = lower([
    item.title,
    item.subject ?? "",
    item.body,
    item.ctaLabel ?? "",
    item.ctaUrl ?? "",
    item.lovableExternalId ?? "",
    item.source,
    jsonText(item.designJson),
    jsonText(item.metadata),
  ].join(" "));
  const needles = [
    play.id,
    play.label,
    play.campaignName,
    play.contentTitle,
    play.subject,
    ...play.targetListHints,
  ].map((value) => lower(value)).filter(Boolean);
  return needles.some((needle) => haystack.includes(needle));
}

function bestCampaignPlannerContent(play: CampaignStudioPlay, channel: Channel, content: ContentAsset[]) {
  const activeChannelContent = content.filter((item) => item.channel === channel && item.status !== "archived");
  return activeChannelContent.find((item) => contentMatchesCampaignPlay(play, channel, item)) ?? null;
}

function campaignPlayForContentAsset(contentAsset: ContentAsset) {
  return campaignStudioPlays.find((play) => contentMatchesCampaignPlay(play, contentAsset.channel, contentAsset))
    ?? campaignStudioPlays.find((play) => play.defaultChannel === contentAsset.channel)
    ?? campaignStudioPlays[0];
}

function campaignDraftFromContentAsset(contentAsset: ContentAsset, play: CampaignStudioPlay, targetAudience: MarketingAudience | null): CampaignDraft {
  return {
    name: `${contentAsset.title} campaign`,
    audienceType: play.audienceType,
    channel: contentAsset.channel,
    contentAssetId: contentAsset.id,
    channelContentAssetIds: {
      [contentAsset.channel]: contentAsset.id,
    },
    status: "draft",
    scheduleStartsAt: "",
    scheduleEndsAt: "",
    objective: [
      `Campaign starter created from saved content asset "${contentAsset.title}".`,
      contentAsset.subject ? `Hook: ${contentAsset.subject}` : "",
      contentAsset.body ? `Copy: ${contentAsset.body}` : "",
      `Audience: ${play.audienceType.toUpperCase()}${targetAudience ? ` via ${targetAudience.name}` : ""}.`,
      `Primary channel: ${channelLabel[contentAsset.channel]}.`,
      contentAsset.ctaLabel || contentAsset.ctaUrl ? `CTA: ${contentAsset.ctaLabel || "Open link"}${contentAsset.ctaUrl ? ` (${contentAsset.ctaUrl})` : ""}.` : "",
      "Next step: review recipients, add timing if needed, then add the campaign.",
    ].filter(Boolean).join("\n"),
    targetAudienceId: targetAudience?.id ?? "",
    recipientFilter: "",
    snapshotRecipients: Boolean(targetAudience?.mappedMemberCount),
  };
}

function campaignStudioSubject(play: CampaignStudioPlay, channel: Channel, angleId: CampaignStudioAngleId, target: string) {
  const base = channel === "email" ? play.subject : `${play.label}: ${play.subject}`;
  if (angleId === "proof") return channel === "email" ? `Proof point: ${play.subject}` : `${play.label}: proof point`;
  if (angleId === "action") return channel === "email" ? `Next step: ${play.subject}` : `${play.label}: next step`;
  if (angleId === "local") return channel === "email" ? `${play.subject} for ${target}` : `${play.label} for ${target}`;
  return base;
}

function campaignStudioBrief(
  play: CampaignStudioPlay,
  toneId: CampaignStudioToneId,
  angleId: CampaignStudioAngleId,
  channel: Channel,
  audience: MarketingAudience | null,
): CampaignStudioGeneratedDraft {
  const tone = campaignStudioToneLabel[toneId];
  const target = audience ? audience.name : play.audienceType.toUpperCase();
  const channelGuidance = campaignStudioChannelGuidance[channel];
  const body = [
    play.body,
    "",
    `Tone direction: ${campaignStudioToneGuidance[toneId]}`,
    `Angle direction: ${campaignStudioAngleGuidance[angleId]}`,
    `Channel direction: ${channelGuidance}`,
  ].join("\n");
  return {
    campaignName: play.campaignName,
    contentTitle: `${play.contentTitle} - ${channelLabel[channel]}`,
    subject: campaignStudioSubject(play, channel, angleId, target),
    body,
    ctaLabel: play.ctaLabel,
    ctaUrl: play.ctaUrl,
    language: "en",
    source: "template",
    designJson: {
      generator: "marketing_campaign_studio_template",
      playId: play.id,
      playCategory: play.categoryId,
      tone: toneId,
      angle: angleId,
      channel,
      audience: audience ? audienceSnapshot(audience) : null,
    },
    objective: [
      play.objective,
      "",
      `Audience: ${target}.`,
      `Tone: ${tone}.`,
      `Angle: ${campaignStudioAngleOptions.find((item) => item.id === angleId)?.label ?? angleId}. ${campaignStudioAngleGuidance[angleId]}`,
      `Primary channel: ${channelLabel[channel]}. ${channelGuidance}`,
    ].join("\n"),
  };
}

function campaignStudioVariantSubjectBase(subject: string, fallback: string) {
  const value = (subject || fallback).trim();
  return value.replace(/^(proof point|next step|a gentle invite|local angle):\s*/i, "").trim() || value;
}

function buildCampaignStudioCreativeVariants(
  play: CampaignStudioPlay,
  generated: CampaignStudioGeneratedDraft,
  audience: MarketingAudience | null,
  channel: Channel,
): CampaignStudioCreativeVariant[] {
  const audienceName = audience?.name ?? play.audienceType.toUpperCase();
  const baseSubject = campaignStudioVariantSubjectBase(generated.subject, play.subject || generated.campaignName);
  const localSubject = baseSubject.replace(/\s+for\s+.+$/i, "").trim() || baseSubject;
  const ctaUrl = generated.ctaUrl.trim() || play.ctaUrl || "https://v2.vyva.life";
  const currentCta = generated.ctaLabel.trim() || play.ctaLabel || "Learn more";
  return [
    {
      key: "clear-next-step",
      label: "Clear next step",
      focus: "Conversion",
      subject: `Next step: ${baseSubject}`,
      ctaLabel: currentCta,
      ctaUrl,
      detail: `Best when ${audienceName} needs one obvious action in ${channelLabel[channel]}.`,
    },
    {
      key: "proof-led",
      label: "Proof-led",
      focus: "Trust",
      subject: `Proof point: ${baseSubject}`,
      ctaLabel: "See the proof",
      ctaUrl,
      detail: "Best for skeptical audiences, partner outreach, and credibility-led campaigns.",
    },
    {
      key: "local-fit",
      label: "Local fit",
      focus: "Relevance",
      subject: `${localSubject} for ${audienceName}`,
      ctaLabel: "See local details",
      ctaUrl,
      detail: "Best when the list, venue, market, or community context should feel specific.",
    },
    {
      key: "soft-invite",
      label: "Soft invite",
      focus: "Relationship",
      subject: `A gentle invite: ${baseSubject}`,
      ctaLabel: "I want the details",
      ctaUrl,
      detail: "Best for caregivers, families, and low-pressure follow-up.",
    },
  ];
}

function objectValue(value: unknown, key: string) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return "";
  const item = (value as Record<string, unknown>)[key];
  return typeof item === "string" ? item : "";
}

function recipientSnapshotLabel(recipient: CampaignRecipient) {
  return objectValue(recipient.snapshot, "fullName") || objectValue(recipient.snapshot, "email") || recipient.recipient;
}

function recipientSnapshotText(recipient: CampaignRecipient, keys: string[]) {
  const snapshot = recordValue(recipient.snapshot);
  const lovable = recordValue(snapshot.lovable);
  const nestedContact = recordValue(lovable.contact ?? snapshot.contact);
  for (const source of [snapshot, lovable, nestedContact]) {
    for (const key of keys) {
      const value = source[key];
      if (typeof value === "string" && value.trim()) return value.trim();
    }
  }
  return "";
}

function recipientContactLookupKeys(recipient: CampaignRecipient) {
  return [
    recipient.contactId,
    recipientSnapshotText(recipient, ["contactExternalId", "contact_external_id", "contactId", "contact_id", "externalId", "external_id", "lovableExternalId", "lovable_external_id", "id"]),
  ].flatMap((value) => lookupKeysForExternalId(value, ["contact"]));
}

function recipientEmailLookupKey(recipient: CampaignRecipient) {
  return lower(recipientSnapshotText(recipient, ["email", "emailAddress", "email_address"]) || recipient.recipient);
}

function sumMarketingMetrics(metrics: MarketingCampaignMetric[]): MarketingAnalyticsTotals {
  return metrics.reduce((totals, metric) => ({
    sent: totals.sent + metric.sent,
    delivered: totals.delivered + metric.delivered,
    opened: totals.opened + metric.opened,
    clicked: totals.clicked + metric.clicked,
    bounced: totals.bounced + metric.bounced,
    unsubscribed: totals.unsubscribed + metric.unsubscribed,
    replied: totals.replied + metric.replied,
    socialEngagement: totals.socialEngagement + metric.socialEngagement,
  }), { sent: 0, delivered: 0, opened: 0, clicked: 0, bounced: 0, unsubscribed: 0, replied: 0, socialEngagement: 0 });
}

function metricRate(numerator: number, denominator: number) {
  if (denominator <= 0) return 0;
  return Math.round((numerator / denominator) * 100);
}

function metricRateLabel(numerator: number, denominator: number) {
  return denominator > 0 ? `${metricRate(numerator, denominator)}%` : "No data";
}

function summarizeCampaignMetrics(metrics: MarketingCampaignMetric[]): CampaignMetricSummary {
  const totals = sumMarketingMetrics(metrics);
  const latestMetricDate = metrics
    .map((metric) => metric.metricDate)
    .filter((value): value is string => Boolean(value))
    .sort((a, b) => new Date(b).getTime() - new Date(a).getTime())[0] ?? null;
  return {
    ...totals,
    metricCount: metrics.length,
    latestMetricDate,
    channels: Array.from(new Set(metrics.map((metric) => metric.channel).filter(Boolean))).sort(),
  };
}

function contactProfileSignals(contact: MarketingContact) {
  const metadata = recordValue(contact.metadata);
  const lovable = recordValue(metadata.lovable);
  const profile = recordValue(lovable.profile ?? metadata.profile);
  const segmentation = recordValue(metadata.segmentation ?? lovable.segmentation);
  const sources = [metadata, lovable, profile, segmentation];
  const entries = [
    {
      key: "crmScore",
      label: "CRM",
      value: firstMetadataText(sources, ["crmScore", "crm_score", "leadScore", "lead_score", "score", "profile.crmScore", "profile.crm_score"]),
      className: "bg-emerald-50 text-emerald-800",
    },
    {
      key: "lifecycle",
      label: "Lifecycle",
      value: firstMetadataText(sources, ["lifecycle", "lifeCycle", "life_cycle", "stage", "profile.lifecycle", "segmentation.lifecycle"]),
      className: "bg-blue-50 text-blue-800",
    },
    {
      key: "persona",
      label: "Persona",
      value: firstMetadataText(sources, ["persona", "profile.persona", "segment", "profile.segment"]),
      className: "bg-purple-50 text-purple-800",
    },
    {
      key: "profileEmail",
      label: "Profile email",
      value: firstMetadataText(sources, ["profile.emailAddress", "profile.email_address", "profile.email", "emailAddress", "email_address"]),
      className: "bg-[#f5eee8] text-[#5b4a46]",
    },
  ].filter((entry) => entry.value);
  return entries;
}

function contactSearchText(contact: MarketingContact) {
  const profileSignals = contactProfileSignals(contact);
  return [
    contact.id,
    contact.fullName,
    contact.email,
    contact.phoneNumber,
    contact.whatsappNumber,
    contact.consentStatus,
    contact.roleLabel,
    contact.companyName,
    contact.language,
    contact.category,
    contact.vertical,
    contact.market,
    contact.source,
    contact.lovableExternalId,
    contact.profileId,
    contact.organizationId,
    contact.channelAvailability,
    contact.metadata,
    ...profileSignals.flatMap((entry) => [entry.label, entry.value]),
    ...(contact.tags ?? []),
    ...(contact.lists ?? []),
  ].map(searchableValue).join(" ");
}

function countedOptions(values: Array<string | null | undefined>): CountOption[] {
  const counts = new Map<string, { label: string; count: number }>();
  for (const rawValue of values) {
    const label = String(rawValue ?? "").trim();
    if (!label) continue;
    const value = label.toLowerCase();
    const current = counts.get(value);
    if (current) {
      current.count += 1;
    } else {
      counts.set(value, { label, count: 1 });
    }
  }
  return Array.from(counts.entries())
    .map(([value, item]) => ({ value, label: item.label, count: item.count }))
    .sort((a, b) => a.label.localeCompare(b.label));
}

function selectedOptionLabel(options: CountOption[], value: string) {
  return options.find((option) => option.value === value)?.label ?? value;
}

function topCountLabels(values: Array<string | null | undefined>, fallback = "Unknown", limit = 2) {
  return countedOptions(values.map((value) => String(value ?? "").trim() || fallback))
    .sort((a, b) => b.count - a.count || a.label.localeCompare(b.label))
    .slice(0, limit)
    .map((item) => `${item.label} ${item.count}`);
}

function audienceStrategyBrief(audience: MarketingAudience, contacts: MarketingContact[]): AudienceStrategyBrief {
  const mappedContacts = contacts.filter((contact) => contactMatchesMemberIds(contact, audience.contactExternalIds));
  const totalMembers = Math.max(audience.memberCount, audience.contactExternalIds.length, mappedContacts.length);
  const emailReadyContacts = mappedContacts.filter((contact) => Boolean(recipientForChannel(contact, "email")));
  const whatsappReadyContacts = mappedContacts.filter((contact) => Boolean(recipientForChannel(contact, "whatsapp")));
  const reachableContacts = mappedContacts.filter((contact) => Boolean(recipientForChannel(contact, "email") || recipientForChannel(contact, "whatsapp")));
  const consentReviewContacts = mappedContacts.filter((contact) => contact.consentStatus !== "opted_in");
  const optedOutCount = mappedContacts.filter((contact) => contact.consentStatus === "opted_out").length;
  const segmentedCount = mappedContacts.filter((contact) => Boolean(
    contact.language
    || contact.category
    || contact.vertical
    || contact.market
    || contact.tags.length
    || contact.lists.length,
  )).length;
  const b2bCount = mappedContacts.filter((contact) => (
    contact.audienceType === "b2b"
    || contact.audienceType === "both"
    || Boolean(contact.companyName || contact.roleLabel)
  )).length;
  const b2cCount = mappedContacts.filter((contact) => contact.audienceType === "b2c" || contact.audienceType === "both").length;
  const audienceHaystack = lower([
    audience.name,
    audience.description,
    audience.listType,
    audience.source,
    audience.lovableExternalId,
    JSON.stringify(audience.rules ?? {}),
    JSON.stringify(audience.metadata ?? {}),
  ].filter(Boolean).join(" "));
  const partnerSignal = ["partner", "provider", "clinic", "pharmacy", "referral", "b2b", "organization", "organisation"].some((signal) => audienceHaystack.includes(signal));
  const familySignal = ["family", "caregiver", "elder", "senior", "b2c", "user"].some((signal) => audienceHaystack.includes(signal));
  const localSignal = mappedContacts.some((contact) => Boolean(contact.market)) || ["local", "madrid", "spain", "city", "community", "event"].some((signal) => audienceHaystack.includes(signal));
  const audienceType: Audience = (b2bCount > 0 && b2cCount > 0)
    ? "both"
    : b2bCount > b2cCount || partnerSignal
      ? "b2b"
      : b2cCount > 0 || familySignal
        ? "b2c"
        : "both";
  const playId: CampaignStudioPlayId = audienceType === "b2b"
    ? "b2b-partner-outreach"
    : localSignal
      ? "local-event"
      : consentReviewContacts.length > 0
        ? "reactivation"
        : "caregiver-onboarding";
  const toneId: CampaignStudioToneId = audienceType === "b2b" ? "expert" : localSignal ? "uplifting" : "warm";
  const angleId: CampaignStudioAngleId = audienceType === "b2b" ? "proof" : localSignal ? "local" : consentReviewContacts.length > 0 ? "balanced" : "action";
  const primaryChannel: Channel = emailReadyContacts.length >= whatsappReadyContacts.length ? "email" : "whatsapp";
  const channels = uniqueChannels(audienceType === "b2b"
    ? [primaryChannel, "linkedin", "email", "whatsapp"]
    : localSignal
      ? [primaryChannel, "facebook", "instagram", "whatsapp"]
      : [primaryChannel, "whatsapp", "email"]);
  const percent = (value: number, total: number) => total > 0 ? Math.round((value / total) * 100) : 0;
  const mappedScore = percent(mappedContacts.length, totalMembers || mappedContacts.length);
  const reachScore = percent(reachableContacts.length, mappedContacts.length);
  const consentScore = percent(mappedContacts.length - consentReviewContacts.length, mappedContacts.length);
  const segmentationScore = percent(segmentedCount, mappedContacts.length);
  const score = mappedContacts.length
    ? Math.round((mappedScore + reachScore + consentScore + segmentationScore) / 4)
    : 0;
  const state: CampaignReadinessState = totalMembers === 0 || mappedContacts.length === 0 || reachableContacts.length === 0
    ? "blocked"
    : audience.unmappedContactExternalIds.length > 0 || consentReviewContacts.length > 0 || segmentedCount < mappedContacts.length
      ? "needs_action"
      : "ready";
  const topMarkets = topCountLabels(mappedContacts.map((contact) => contact.market), "Unknown", 2);
  const topVerticals = topCountLabels(mappedContacts.map((contact) => contact.vertical), "Unknown", 2);
  const topLanguages = topCountLabels(mappedContacts.map((contact) => contact.language), "Unknown", 2);
  const nextMove = playId === "b2b-partner-outreach"
    ? "Build a proof-led partner sequence with one clear intro or demo ask."
    : playId === "local-event"
      ? "Build a localised campaign around one place, moment, or community CTA."
      : playId === "reactivation"
        ? "Run a soft reactivation campaign after consent and channel cleanup."
        : "Build a warm onboarding campaign that moves people to one useful care-team action.";
  const cleanup = audience.unmappedContactExternalIds.length > 0
    ? `Map ${audience.unmappedContactExternalIds.length} imported list member ID${audience.unmappedContactExternalIds.length === 1 ? "" : "s"} before relying on this list for snapshots.`
    : consentReviewContacts.length > 0
      ? `Review consent for ${consentReviewContacts.length} mapped contact${consentReviewContacts.length === 1 ? "" : "s"} before automation.`
      : segmentedCount < mappedContacts.length
        ? `Add language, market, tag, category, or vertical data for ${mappedContacts.length - segmentedCount} contact${mappedContacts.length - segmentedCount === 1 ? "" : "s"}.`
        : "List is ready for campaign planning and recipient snapshots.";
  const sampleContacts = reachableContacts.slice(0, 3).map((contact) => [
    contact.fullName || contact.email || contact.phoneNumber || "Unnamed contact",
    contact.email || contact.whatsappNumber || contact.phoneNumber || "no direct route",
    contact.companyName || contact.roleLabel || contact.market || "",
  ].filter(Boolean).join(" - "));
  const promptText = [
    `VYVA audience strategy brief: ${audience.name}`,
    `List type/source: ${audience.listType} / ${audience.source}`,
    `Audience fit: ${audienceType.toUpperCase()}`,
    `Readiness: ${readinessLabel(state)} (${score}%)`,
    `Members: ${mappedContacts.length}/${totalMembers} mapped; ${reachableContacts.length} reachable; ${audience.unmappedContactExternalIds.length} unmapped imported IDs`,
    `Channels: ${channels.map((channel) => channelLabel[channel]).join(", ")}; primary ${channelLabel[primaryChannel]}`,
    `Consent: ${consentReviewContacts.length} need review, ${optedOutCount} opted out`,
    `Segments: markets ${topMarkets.join(" / ") || "Unknown"}; verticals ${topVerticals.join(" / ") || "Unknown"}; languages ${topLanguages.join(" / ") || "Unknown"}`,
    "",
    `Recommended move: ${nextMove}`,
    `Cleanup: ${cleanup}`,
    sampleContacts.length ? `Sample contacts: ${sampleContacts.join("; ")}` : "Sample contacts: none mapped yet",
    "",
    "AI task:",
    `Create a concise campaign plan for this list. Use ${channels.map((channel) => channelLabel[channel]).join(", ")}. Keep the offer practical, consent-safe, localized when market data exists, and include one human relationship follow-up step after replies or clicks.`,
  ].join("\n");

  return {
    audienceType,
    state,
    score,
    playId,
    toneId,
    angleId,
    primaryChannel,
    channels,
    totalMembers,
    mappedContacts,
    reachableContacts,
    emailReady: emailReadyContacts.length,
    whatsappReady: whatsappReadyContacts.length,
    consentReviewCount: consentReviewContacts.length,
    optedOutCount,
    segmentedCount,
    topMarkets,
    topVerticals,
    topLanguages,
    nextMove,
    cleanup,
    promptText,
  };
}

function audienceLaunchChecklist(audience: MarketingAudience, strategy: AudienceStrategyBrief): AudienceLaunchChecklistItem[] {
  const unmappedCount = audience.unmappedContactExternalIds.length;
  const mappedCount = strategy.mappedContacts.length;
  const reachableCount = strategy.reachableContacts.length;
  const missingSegments = Math.max(mappedCount - strategy.segmentedCount, 0);
  const allMapped = mappedCount > 0 && unmappedCount === 0;
  const consentClean = strategy.consentReviewCount === 0;
  const optedOutOnly = mappedCount > 0 && strategy.optedOutCount >= mappedCount;
  const hasSegments = mappedCount > 0 && missingSegments === 0;
  const routeReady = reachableCount > 0 && consentClean;

  return [
    {
      key: "mapping",
      title: "List mapping",
      state: mappedCount === 0 ? "blocked" : allMapped ? "ready" : "needs_action",
      detail: mappedCount === 0
        ? "No imported members are mapped to marketing contacts yet."
        : allMapped
          ? `${mappedCount}/${strategy.totalMembers} members are mapped and ready for snapshots.`
          : `${mappedCount}/${strategy.totalMembers} mapped; ${unmappedCount} imported member ID${unmappedCount === 1 ? "" : "s"} still need matching.`,
    },
    {
      key: "reach",
      title: "Reachable channels",
      state: reachableCount > 0 ? "ready" : "blocked",
      detail: reachableCount > 0
        ? `${reachableCount} contact${reachableCount === 1 ? "" : "s"} reachable: ${strategy.emailReady} email, ${strategy.whatsappReady} WhatsApp.`
        : "Add email or WhatsApp details before this list can receive a campaign.",
    },
    {
      key: "consent",
      title: "Consent",
      state: optedOutOnly ? "blocked" : consentClean ? "ready" : "needs_action",
      detail: optedOutOnly
        ? "Every mapped contact is opted out, so this list should not be launched."
        : consentClean
          ? "Consent is clean for the mapped contacts."
          : `${strategy.consentReviewCount} contact${strategy.consentReviewCount === 1 ? "" : "s"} need consent review before automation.`,
    },
    {
      key: "segments",
      title: "Personalisation data",
      state: mappedCount === 0 ? "blocked" : hasSegments ? "ready" : "needs_action",
      detail: hasSegments
        ? `Segments are ready: ${strategy.topMarkets.join(" / ") || "markets unknown"}, ${strategy.topLanguages.join(" / ") || "languages unknown"}.`
        : `Add language, market, category, vertical, tag, or list data for ${missingSegments} contact${missingSegments === 1 ? "" : "s"}.`,
    },
    {
      key: "route",
      title: "Campaign route",
      state: routeReady ? "ready" : reachableCount > 0 ? "needs_action" : "blocked",
      detail: routeReady
        ? `${channelLabel[strategy.primaryChannel]} is the first route; planned channels: ${strategy.channels.map((channel) => channelLabel[channel]).join(", ")}.`
        : `${channelLabel[strategy.primaryChannel]} is recommended, but fix reach/consent before publishing.`,
    },
  ];
}

function valueMatchesFilter(value: string | null | undefined, filter: string) {
  return filter === "all" || String(value ?? "").trim().toLowerCase() === filter;
}

function searchableValue(value: unknown) {
  if (value === null || value === undefined) return "";
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") return String(value).toLowerCase();
  try {
    return JSON.stringify(value).toLowerCase();
  } catch {
    return "";
  }
}

function matchesSearch(search: string, values: unknown[]) {
  const query = search.trim().toLowerCase();
  if (!query) return true;
  return values.map(searchableValue).join(" ").includes(query);
}

function displayText(value: unknown) {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value.trim();
  if (typeof value === "number" && Number.isFinite(value)) return String(value);
  if (typeof value === "boolean") return value ? "yes" : "no";
  return "";
}

function nestedValue(source: Record<string, unknown>, path: string) {
  let current: unknown = source;
  for (const segment of path.split(".")) {
    if (!current || typeof current !== "object" || Array.isArray(current)) return undefined;
    current = (current as Record<string, unknown>)[segment];
  }
  return current;
}

function firstMetadataText(sources: Record<string, unknown>[], paths: string[]) {
  for (const source of sources) {
    for (const path of paths) {
      const text = displayText(nestedValue(source, path));
      if (text) return text;
    }
  }
  return "";
}

