function recordValue(value: unknown) {
  return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function recordArray(value: unknown) {
  return Array.isArray(value) ? value.map(recordValue).filter((item) => Object.keys(item).length > 0) : [];
}

function launchPacketTextFromMetadata(packet: Record<string, unknown>) {
  const channels = recordArray(packet.channels);
  const reviewChecklist = Array.isArray(packet.reviewChecklist) ? packet.reviewChecklist.map(displayText).filter(Boolean) : [];
  const visualBriefs = recordArray(packet.visualBriefs);
  const followUpPlays = recordArray(packet.followUpPlays);
  const outcomeTrackers = recordArray(packet.outcomeTrackers);
  const targetAudience = recordValue(packet.targetAudience);
  const targetAudienceName = displayText(targetAudience.name);

  return [
    "VYVA saved launch packet",
    `Template pack: ${displayText(packet.packTitle) || "Unknown"}`,
    `Audience: ${displayText(packet.audienceType).toUpperCase() || "UNKNOWN"}`,
    targetAudienceName ? `Target list: ${targetAudienceName}` : "",
    displayText(packet.scheduleStartsAt) ? `Starts: ${formatDate(displayText(packet.scheduleStartsAt))}` : "Starts: Not scheduled",
    displayText(packet.focus) ? `Focus: ${displayText(packet.focus)}` : "",
    displayText(packet.routeSummary) ? `Route summary: ${displayText(packet.routeSummary)}` : "",
    "",
    "Launch order:",
    ...(channels.length ? channels.map((route, index) => [
      `${index + 1}. ${displayText(route.channelLabel) || displayText(route.channel) || "Channel"}`,
      `Content: ${displayText(route.contentTitle) || "Missing"}`,
      `When: ${displayText(route.scheduledAt) ? formatDate(displayText(route.scheduledAt)) : "Not scheduled"}`,
      `Mode: ${displayText(route.sendMode) || "Review"}`,
      `Owner: ${displayText(route.owner) || "Marketing admin"}`,
      `Recipients: ${displayText(route.recipientCount) || "0"}`,
      `Next: ${displayText(route.nextAction) || "Review before launch."}`,
    ].join(" | ")) : ["No channels saved."]),
    "",
    "Review checklist:",
    ...(reviewChecklist.length ? reviewChecklist.map((item) => `- ${item}`) : ["- Review campaign setup before launch."]),
    "",
    "Visual briefs:",
    ...(visualBriefs.length ? visualBriefs.map((item) => `- ${displayText(item.title) || "Visual"} (${displayText(item.format) || "format"}): ${displayText(item.text)}`) : ["- No visual brief saved."]),
    "",
    "Follow-up plays:",
    ...(followUpPlays.length ? followUpPlays.map((item) => `- ${displayText(item.trigger) || "Trigger"}: ${displayText(item.action)} Owner: ${displayText(item.owner) || "Marketing admin"}`) : ["- No follow-up play saved."]),
    "",
    "Outcome trackers:",
    ...(outcomeTrackers.length ? outcomeTrackers.map((item) => `- ${displayText(item.metric) || "Metric"}: ${displayText(item.target)} Source: ${displayText(item.source)}`) : ["- No outcome tracker saved."]),
    "",
    "AI prompt:",
    displayText(packet.aiPrompt) || "Improve this campaign while preserving the target audience, channels, consent, and relationship follow-up.",
  ].filter((line) => line !== "").join("\n");
}

function numberValue(value: unknown) {
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

function syncCountItems(summary: Record<string, unknown>, group: "exported" | "imported" | "skipped") {
  const source = recordValue(summary[group]);
  return (Object.keys(syncCountLabels) as SyncCountKey[])
    .map((key) => ({ key, label: syncCountLabels[key], value: numberValue(source[key]) }))
    .filter((item) => item.value > 0);
}

function syncCountValue(summary: Record<string, unknown>, group: "exported" | "imported" | "skipped", key: SyncCountKey) {
  return numberValue(recordValue(summary[group])[key]);
}

function syncParityItems(summary: Record<string, unknown>) {
  return (Object.keys(syncCountLabels) as SyncCountKey[])
    .map((key) => {
      const exported = syncCountValue(summary, "exported", key);
      const imported = syncCountValue(summary, "imported", key);
      const skipped = syncCountValue(summary, "skipped", key);
      const missing = Math.max(exported - imported - skipped, 0);
      return {
        key,
        label: syncCountLabels[key],
        exported,
        imported,
        skipped,
        missing,
        status: exported === 0 && imported > 0 ? "derived" : exported === 0 ? "empty" : missing > 0 ? "missing" : skipped > 0 ? "review" : "complete",
      };
    })
    .filter((item) => item.exported > 0 || item.imported > 0 || item.skipped > 0);
}

function syncUnmappedCount(summary: Record<string, unknown>) {
  return numberValue(recordValue(summary.unmapped).audienceContactExternalIdCount);
}

function syncUnmappedCampaignRecipientCount(summary: Record<string, unknown>) {
  return numberValue(recordValue(summary.unmapped).campaignRecipientExternalIdCount);
}

function syncUnmappedSample(summary: Record<string, unknown>) {
  const unmapped = recordValue(summary.unmapped);
  const ids = [
    ...(Array.isArray(unmapped.audienceContactExternalIds) ? unmapped.audienceContactExternalIds : []),
    ...(Array.isArray(unmapped.campaignRecipientExternalIds) ? unmapped.campaignRecipientExternalIds : []),
  ];
  return ids.map((id) => String(id)).filter(Boolean).slice(0, 5);
}

function syncExportMetadata(summary: Record<string, unknown>) {
  const metadata = recordValue(summary.exportMetadata);
  const topLevelKeys = Array.isArray(metadata.topLevelKeys)
    ? metadata.topLevelKeys.map((key) => String(key)).filter(Boolean)
    : [];
  return {
    dataset: typeof metadata.dataset === "string" && metadata.dataset.trim() ? metadata.dataset.trim() : "",
    exportedAt: typeof metadata.exportedAt === "string" && metadata.exportedAt.trim() ? metadata.exportedAt.trim() : "",
    cursor: typeof metadata.cursor === "string" && metadata.cursor.trim() ? metadata.cursor.trim() : "",
    apiUrl: typeof metadata.apiUrl === "string" && metadata.apiUrl.trim() ? metadata.apiUrl.trim() : "",
    topLevelKeys,
  };
}

function syncContentSourceItems(summary: Record<string, unknown>) {
  return Object.entries(recordValue(summary.contentSourceCounts))
    .map(([key, value]) => ({ key, label: contentSourceLabel(key), value: numberValue(value) }))
    .filter((item) => item.value > 0)
    .sort((a, b) => b.value - a.value || a.label.localeCompare(b.label));
}

function syncContentSourceCount(summary: Record<string, unknown>, keys: string[]) {
  const counts = recordValue(summary.contentSourceCounts);
  return keys.reduce((total, key) => total + numberValue(counts[key]), 0);
}

function syncDestinationCount(summary: Record<string, unknown>, row: typeof lovableDestinationRows[number]) {
  const sourceCount = row.contentSourceKeys?.length ? syncContentSourceCount(summary, row.contentSourceKeys) : 0;
  if (sourceCount) return sourceCount;
  const exported = row.countKeys.reduce((total, key) => total + syncCountValue(summary, "exported", key), 0);
  if (exported) return exported;
  const imported = row.countKeys.reduce((total, key) => total + syncCountValue(summary, "imported", key), 0);
  if (imported) return imported;
  return row.countKeys.reduce((total, key) => total + numberValue(summary[key]), 0);
}

