  async function createContentAssetsFromTemplatePack(pack: ContentTemplatePack, templates: ContentTemplate[]) {
    if (!templates.length) {
      const feedback = `${pack.title} has no templates to save.`;
      setContentActionFeedback(feedback);
      setContentFeedback(feedback);
      setMessage(feedback);
      return;
    }

    setContentSaving(true);
    setContentActionFeedback(`Creating ${templates.length} ${pack.title} content asset${templates.length === 1 ? "" : "s"}...`);
    setContentFeedback("");
    setMessage(`Creating content assets from ${pack.title}...`);
    try {
      const created: ContentAsset[] = [];
      for (const template of templates) {
        const draft = contentDraftFromTemplate(template);
        const response = await api<{ content: ContentAsset }>("/api/admin/marketing/content", {
          method: "POST",
          body: JSON.stringify({
            ...contentCreatePayloadFromDraft(draft),
            source: "vyva",
            lovableExternalId: null,
            metadata: {
              generatedFrom: "template_pack",
              packId: pack.id,
              packTitle: pack.title,
              packFocus: pack.focus,
              templateId: template.id,
              templateTitle: template.title,
              studioPlayId: pack.studioPlayId,
              tone: pack.toneId,
              angle: pack.angleId,
              aiPrompt: pack.aiPrompt,
            },
          }),
        });
        created.push(response.content);
      }

      const firstCreated = created[0] ?? null;
      const createdById = new Map(created.map((item) => [item.id, item]));
      setContent((current) => [
        ...createdById.values(),
        ...current.filter((item) => !createdById.has(item.id)),
      ]);
      if (firstCreated) {
        setSelectedContentId(firstCreated.id);
        setEditingContentId(firstCreated.id);
        setContentEditDraft(contentEditDraftFromContent(firstCreated));
        setContentDrawerMode("edit");
      }
      setContentTemplatePackFilter(pack.id);
      setContentTemplateSearch("");
      setContentTemplateChannelFilter("all");
      setContentTemplateAudienceFilter("all");
      setContentTemplateCategoryFilter("all");
      const feedback = `Created ${created.length} ${pack.title} content asset${created.length === 1 ? "" : "s"}. ${firstCreated ? "First asset opened for review." : ""}`;
      setContentActionFeedback(feedback);
      setContentFeedback(feedback);
      setMessage(feedback);
      await refreshAll();
      scrollToContentPanel(contentEditorPanelRef);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : `${pack.title} content assets could not be created.`;
      setContentActionFeedback(errorMessage);
      setContentFeedback(errorMessage);
      setMessage(errorMessage);
    } finally {
      setContentSaving(false);
    }
  }

  async function createCampaignPlanFromTemplatePack(
    pack: ContentTemplatePack,
    templates: ContentTemplate[],
    heroTemplate: ContentTemplate | null,
    options: { routeChannels?: Channel[]; onError?: (message: string) => void } = {},
  ): Promise<MarketingDashboardAiCreatedKitSummary | null> {
    if (!templates.length) {
      const feedback = `${pack.title} has no templates to turn into a campaign.`;
      setContentActionFeedback(feedback);
      setCampaignStudioFeedback(feedback);
      setMessage(feedback);
      return null;
    }

    const play = campaignStudioPlays.find((item) => item.id === pack.studioPlayId) ?? campaignStudioPlays[0];
    const audienceType = templatePackAudience(pack, heroTemplate, play);
    const targetAudience = bestCampaignStudioAudience(play, audiences);
    const targetAudienceSnapshot = audienceSnapshot(targetAudience);
    const scheduleStartsAt = fromDateTimeLocal(campaignStudioDefaultSchedule(play));
    const allPackRouteChannels = uniqueChannels([
      heroTemplate?.channel ?? play.defaultChannel,
      ...pack.sequence.map((step) => step.channel),
      ...templates.map((template) => template.channel),
    ]);
    const requestedRouteChannels = options.routeChannels?.length ? uniqueChannels(options.routeChannels) : null;
    const routeChannels = requestedRouteChannels
      ? uniqueChannels(requestedRouteChannels.filter((channel) => allPackRouteChannels.includes(channel)))
      : allPackRouteChannels;
    const activeRouteChannels = routeChannels.length ? routeChannels : allPackRouteChannels;
    const planTemplates = requestedRouteChannels
      ? templates.filter((template) => activeRouteChannels.includes(template.channel))
      : templates;
    const campaignTemplates = planTemplates.length ? planTemplates : templates;
    const planHeroTemplate = heroTemplate && activeRouteChannels.includes(heroTemplate.channel)
      ? heroTemplate
      : campaignTemplates.find((template) => activeRouteChannels.includes(template.channel)) ?? heroTemplate;
    const sequenceTemplates = pack.sequence.map((step) => ({
      step,
      template: step.templateId
        ? campaignTemplates.find((template) => template.id === step.templateId) ?? contentTemplateGallery.find((template) => template.id === step.templateId) ?? null
        : null,
    }));
    const routeTemplateByChannel = new Map<Channel, ContentTemplate>();
    for (const channel of activeRouteChannels) {
      const sequenceTemplate = sequenceTemplates.find((item) => item.step.channel === channel && item.template)?.template;
      const fallbackTemplate = campaignTemplates.find((template) => template.channel === channel) ?? planHeroTemplate ?? campaignTemplates[0];
      if (sequenceTemplate || fallbackTemplate) routeTemplateByChannel.set(channel, sequenceTemplate ?? fallbackTemplate);
    }
    const eligibleContacts = contacts.filter((contact) => (
      campaignAllowsContact(audienceType, contact.audienceType)
      && contactMatchesAudienceList(contact, targetAudience)
    ));

    setContentSaving(true);
    setCampaignSaving(true);
    setContentActionFeedback(`Creating ${pack.title} campaign plan...`);
    setCampaignStudioFeedback(`Creating ${pack.title} campaign plan with content, channels, and recipient snapshots...`);
    setMessage(`Creating campaign plan from ${pack.title}...`);
    try {
      const contentByTemplateId = new Map<string, ContentAsset>();
      const createdContent: ContentAsset[] = [];

      for (const template of campaignTemplates) {
        const existing = content.find((item) => contentAssetMatchesTemplatePack(item, pack, template));
        if (existing) {
          contentByTemplateId.set(template.id, existing);
          continue;
        }
        const draft = contentDraftFromTemplate(template);
        const response = await api<{ content: ContentAsset }>("/api/admin/marketing/content", {
          method: "POST",
          body: JSON.stringify({
            ...contentCreatePayloadFromDraft(draft),
            source: "vyva",
            lovableExternalId: null,
            metadata: {
              generatedFrom: "template_pack_campaign_plan",
              packId: pack.id,
              packTitle: pack.title,
              packFocus: pack.focus,
              templateId: template.id,
              templateTitle: template.title,
              studioPlayId: pack.studioPlayId,
              tone: pack.toneId,
              angle: pack.angleId,
              aiPrompt: pack.aiPrompt,
            },
          }),
        });
        contentByTemplateId.set(template.id, response.content);
        createdContent.push(response.content);
      }

      const channelContentAssetIds = Object.fromEntries(activeRouteChannels.map((channel) => {
        const template = routeTemplateByChannel.get(channel);
        return [channel, template ? contentByTemplateId.get(template.id)?.id ?? null : null];
      })) as Partial<Record<Channel, string | null>>;
      const channels = activeRouteChannels.map((channel, index) => {
        const sequenceIndex = pack.sequence.findIndex((step) => step.channel === channel);
        const sequenceStep = sequenceIndex >= 0 ? pack.sequence[sequenceIndex] : null;
        const scheduledAt = scheduleWithDelay(
          scheduleStartsAt,
          sequenceStep ? templateSequenceDelayHours(sequenceStep.offset, sequenceIndex) : index * 24,
        );
        return {
          channel,
          contentAssetId: channelContentAssetIds[channel] ?? null,
          status: "draft",
          scheduledAt,
          sendCapability: channel === "email" ? "enabled" : "planning_only",
        };
      });
      const recipients = activeRouteChannels.flatMap((channel) => eligibleContacts.flatMap((contact) => {
        const recipient = recipientForChannel(contact, channel);
        if (!recipient) return [];
        const scheduledAt = channels.find((item) => item.channel === channel)?.scheduledAt ?? scheduleStartsAt;
        return [{
          contactId: contact.id,
          channel,
          recipient,
          status: "planned",
          scheduledAt,
          snapshot: {
            ...recipientSnapshot(contact),
            ...(targetAudienceSnapshot ? { audienceList: targetAudienceSnapshot } : {}),
            templatePackId: pack.id,
            templatePackTitle: pack.title,
            plannerChannel: channel,
          },
        }];
      }));
      const launchPacket = buildTemplatePackLaunchPacket({
        pack,
        audienceType,
        targetAudience: targetAudienceSnapshot,
        scheduleStartsAt,
        routeChannels: activeRouteChannels,
        routeTemplateByChannel,
        contentByTemplateId,
        channels,
        recipients,
      });
      const campaignResult = await api<{ campaign: Campaign }>("/api/admin/marketing/campaigns", {
        method: "POST",
        body: JSON.stringify({
          name: `${pack.title} campaign plan`,
          audienceType,
          status: "draft",
          objective: [
            pack.focus,
            "",
            pack.description,
            "",
            `AI direction: ${pack.aiPrompt}`,
            "",
            "Review note: this creates a draft plan only. Email still requires explicit review/send from campaign details; social, phone, print, and event routes remain manual handoffs.",
          ].join("\n"),
          scheduleStartsAt,
          scheduleEndsAt: null,
          metadata: campaignMetadataWithTarget({
            templatePackPlan: {
              generatedFrom: "template_pack_campaign_plan",
              packId: pack.id,
              packTitle: pack.title,
              studioPlayId: pack.studioPlayId,
              tone: pack.toneId,
              angle: pack.angleId,
              aiPrompt: pack.aiPrompt,
              routeChannels: activeRouteChannels,
              templateIds: campaignTemplates.map((template) => template.id),
              contentAssetIds: channelContentAssetIds,
              sequence: pack.sequence,
              routeFilter: requestedRouteChannels ? activeRouteChannels : undefined,
              launchPacket,
            },
          }, targetAudience),
          channels,
          recipients,
        }),
      });

      await refreshAll();
      const createdById = new Map(createdContent.map((item) => [item.id, item]));
      setContent((current) => [
        ...createdById.values(),
        ...current.filter((item) => !createdById.has(item.id)),
      ]);
      setCampaigns((current) => [campaignResult.campaign, ...current.filter((campaign) => campaign.id !== campaignResult.campaign.id)]);
      setEditingCampaignId(campaignResult.campaign.id);
      setCampaignEditDraft(campaignEditDraftFromCampaign(campaignResult.campaign, audiences));
      setContentTemplatePackFilter(pack.id);
      setContentTemplateSearch("");
      setContentTemplateChannelFilter("all");
      setContentTemplateAudienceFilter("all");
      setContentTemplateCategoryFilter("all");
      setActiveTab("dashboard");
      const reusedCount = campaignTemplates.length - createdContent.length;
      const feedback = `Created ${pack.title} campaign plan with ${activeRouteChannels.length} channel route${activeRouteChannels.length === 1 ? "" : "s"}, ${recipients.length} recipient snapshot${recipients.length === 1 ? "" : "s"}, ${createdContent.length} new content asset${createdContent.length === 1 ? "" : "s"}${reusedCount ? `, and ${reusedCount} reused asset${reusedCount === 1 ? "" : "s"}` : ""}.`;
      setContentActionFeedback(feedback);
      setCampaignStudioFeedback(feedback);
      setMessage(feedback);
      return {
        campaignId: campaignResult.campaign.id,
        campaignName: campaignResult.campaign.name,
        packTitle: pack.title,
        routeChannels: activeRouteChannels,
        recipientCount: recipients.length,
        createdContentCount: createdContent.length,
        reusedContentCount: reusedCount,
      };
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : `${pack.title} campaign plan could not be created.`;
      setContentActionFeedback(errorMessage);
      setCampaignStudioFeedback(errorMessage);
      setMessage(errorMessage);
      options.onError?.(errorMessage);
      return null;
    } finally {
      setCampaignSaving(false);
      setContentSaving(false);
    }
  }

  function loadContentTemplatePackAsJourney(pack: ContentTemplatePack, heroTemplate: ContentTemplate | null) {
    const play = campaignStudioPlays.find((item) => item.id === pack.studioPlayId) ?? campaignStudioPlays[0];
    const audienceType = templatePackAudience(pack, heroTemplate, play);
    const targetAudience = bestCampaignStudioAudience(play, audiences);
    const triggerType = templatePackTriggerType(pack);
    const goalType = templatePackGoalType(pack);
    const steps = pack.sequence.map((sequenceStep, index) => {
      const template = sequenceStep.templateId
        ? contentTemplateGallery.find((item) => item.id === sequenceStep.templateId) ?? null
        : null;
      const linkedContent = content.find((item) => {
        const metadataText = jsonText(item.metadata);
        return Boolean(
          (template?.id && metadataText.includes(template.id))
          || (template?.title && lower(item.title) === lower(template.title))
          || (template?.id && lower(item.lovableExternalId) === lower(template.id))
          || (sequenceStep.templateId && lower(item.lovableExternalId) === lower(sequenceStep.templateId)),
        );
      }) ?? null;
      const channel = template?.channel ?? sequenceStep.channel;
      const templateRef = linkedContent
        ? linkedContent.lovableExternalId ?? linkedContent.id
        : template?.id ?? sequenceStep.templateId ?? "";

      return journeyStarterStepDraft({
        channel,
        contentAsset: linkedContent,
        delayHours: templateSequenceDelayHours(sequenceStep.offset, index),
        notes: `${sequenceStep.offset}: ${sequenceStep.title}. ${sequenceStep.detail}`,
        templateKind: linkedContent ? "content_asset" : "template_gallery",
        templateRef,
        config: {
          source: "template_pack",
          packId: pack.id,
          packTitle: pack.title,
          playId: play.id,
          sequenceOffset: sequenceStep.offset,
          sequenceTitle: sequenceStep.title,
          sequenceDetail: sequenceStep.detail,
          templateId: template?.id ?? sequenceStep.templateId ?? null,
          templateTitle: template?.title ?? sequenceStep.title,
          aiPrompt: pack.aiPrompt,
        },
      });
    });

    setActiveTab("journeys");
    setEditingJourneyId("new");
    setJourneyEditDraft({
      ...emptyJourneyEditDraft(),
      name: `${pack.title} journey`,
      audienceType,
      status: "draft",
      objective: `${pack.focus}\n\n${pack.description}\n\nAI direction: ${pack.aiPrompt}`,
      targetAudienceId: targetAudience?.id ?? "",
      metadataText: jsonText({
        source: "template_pack",
        packId: pack.id,
        packTitle: pack.title,
        studioPlayId: play.id,
        toneId: pack.toneId,
        angleId: pack.angleId,
        templateIds: pack.templateIds,
      }),
      triggerType,
      triggerConfigText: jsonText({
        source: "template_pack",
        packId: pack.id,
        playId: play.id,
      }),
      goalType,
      goalConfigText: jsonText({
        source: "template_pack",
        packId: pack.id,
        suggestedReviewDays: pack.id === "partner-growth" ? 14 : pack.id === "care-confidence-reactivation" ? 10 : 7,
      }),
      exitOnGoal: true,
      steps,
    });
    setConfirmingJourneyDeleteId(null);
    setContentTemplatePackFilter(pack.id);
    setContentActionFeedback(`Loaded ${pack.title} as an editable journey draft.`);
    setJourneyFeedback(`Loaded ${pack.title} journey. Review the steps, then create journey.`);
    setMessage(`Journey loaded from template pack: ${pack.title}.`);
  }

  function scrollToContentPanel(ref: RefObject<HTMLDivElement | null>) {
    window.setTimeout(() => {
      const node = ref.current;
      if (!node) return;
      if (typeof node.scrollIntoView === "function") {
        node.scrollIntoView({ behavior: "smooth", block: "start" });
      }
      if (typeof node.focus === "function") {
        node.focus({ preventScroll: true });
      }
    }, 0);
  }

  function scrollToContentActionRow(contentId: string) {
    window.setTimeout(() => {
      const node = document.getElementById(`marketing-content-row-${contentId}`);
      if (!node) return;
      if (typeof node.scrollIntoView === "function") {
        node.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "nearest" });
      }
    }, 0);
  }

