  function applyCampaignExperimentSuggestion(suggestion: CampaignExperimentSuggestion) {
    const campaign = campaignById.get(suggestion.campaignId);
    if (!campaign) {
      setMessage("Campaign experiment could not be opened.");
      return;
    }
    if (suggestion.experimentType === "deliverability") {
      setActiveTab("contacts");
      setContactView("contacts");
      setContactConsentFilter("opted_out");
      setContactFeedback(`Review contacts before scaling "${campaign.name}".`);
      return;
    }
    const contentAsset = suggestion.contentAssetId ? contentById.get(suggestion.contentAssetId) ?? null : null;
    if (!contentAsset) {
      startCampaignEdit(campaign);
      setMessage(`Opened "${campaign.name}". Attach content before drafting a performance experiment.`);
      return;
    }
    const draft = contentDraftFromCampaignExperiment(campaign, contentAsset, suggestion);
    const targetAudience = campaignTargetAudience(campaign, audiences);
    const play = campaignPlayForContentAsset(contentAsset);
    const intentBrief = campaignIntentBriefFromExperiment(campaign, contentAsset, suggestion, targetAudience);
    const selectedChannels = uniqueChannels([contentAsset.channel, ...campaign.channels.map((channel) => channel.channel)]);
    setCampaignStudioCategory(play.categoryId);
    updateCampaignStudio({
      playId: play.id,
      channel: contentAsset.channel,
      selectedChannels,
      toneId: suggestion.experimentType === "follow_up" ? "warm" : "direct",
      angleId: suggestion.experimentType === "follow_up" ? "proof" : "action",
      targetAudienceId: targetAudience?.id ?? "",
      scheduleStartsAt: campaignStudioDefaultSchedule(play),
    });
    setCampaignIntentBrief(intentBrief);
    setCampaignDraft((current) => ({
      ...current,
      name: `${campaign.name} - ${suggestion.experimentType === "subject" ? "subject test" : suggestion.experimentType === "cta" ? "CTA test" : "follow-up"}`,
      audienceType: campaign.audienceType,
      channel: contentAsset.channel,
      contentAssetId: "",
      status: "draft",
      scheduleStartsAt: "",
      scheduleEndsAt: "",
      objective: intentBrief,
      targetAudienceId: targetAudience?.id ?? "",
      recipientFilter: targetAudience?.name ?? "",
      snapshotRecipients: Boolean(targetAudience?.mappedMemberCount || targetAudience?.memberCount || campaign.recipientCount),
    }));
    setActiveTab("content");
    setSelectedContentId(null);
    setEditingContentId(null);
    setContentEditDraft(null);
    setContentDrawerMode(null);
    setConfirmingContentDeleteId(null);
    setContentDraft(draft);
    setContentTemplateSearch("");
    setContentTemplateChannelFilter("all");
    setContentTemplateAudienceFilter("all");
    setContentTemplateCategoryFilter("all");
    setContentSourceFilter("all");
    setContentActionFeedback(`Drafted ${suggestion.experimentType === "cta" ? "CTA" : suggestion.experimentType === "subject" ? "subject line" : "follow-up"} experiment from "${campaign.name}". Campaign AI brief also updated from performance data.`);
    setCampaignStudioFeedback(`Performance brief loaded from "${campaign.name}". Review the AI brief in the campaign studio, then create the next test.`);
    setMessage(`Performance experiment drafted from "${campaign.name}" and loaded into the campaign AI brief.`);
  }

  function cancelContentEdit() {
    setEditingContentId(null);
    setContentEditDraft(null);
    setContentDrawerMode(null);
    setContentFeedback("");
    setContentActionFeedback("");
    setConfirmingContentDeleteId(null);
  }

  function closeContentDrawer() {
    if (contentDrawerMode === "edit") {
      cancelContentEdit();
      return;
    }
    setContentDrawerMode(null);
    setContentActionFeedback("");
  }

  function openContentUsageCampaign(campaignId: string) {
    const campaign = campaignById.get(campaignId);
    if (!campaign) {
      setMessage("Campaign reference could not be opened.");
      return;
    }
    closeContentDrawer();
    startCampaignEdit(campaign);
    setActiveTab("dashboard");
  }

  function openContentUsageJourney(journeyId: string) {
    const journey = journeyById.get(journeyId);
    if (!journey) {
      setMessage("Journey reference could not be opened.");
      return;
    }
    closeContentDrawer();
    startJourneyEdit(journey);
    setActiveTab("journeys");
  }

  async function generateContentStarterCopy(draftOverride?: ContentEditDraft) {
    const currentDraft = draftOverride ?? contentEditDraft;
    if (!currentDraft) return;
    const titleSeed = currentDraft.title.trim() || "Untitled Source content";
    const existingDesign = optionalJsonRecordText(currentDraft.designJsonText);
    const existingMetadata = optionalJsonRecordText(currentDraft.metadataText);
    const sourceMetadata = recordValue(existingMetadata.lovable);
    const sourceType = String(existingMetadata.lovable_source_type ?? sourceMetadata.sourceType ?? sourceMetadata.type ?? "imported content");
    const sourceId = currentDraft.lovableExternalId.trim() || String(sourceMetadata.id ?? "");
    const toneLabel = campaignStudioToneLabel[contentPolishTone];

    setContentStarterRunning(true);
    setContentFeedback(`Generating starter copy in a ${toneLabel.toLowerCase()} tone...`);
    setContentActionFeedback(`AI is drafting starter copy for "${titleSeed}".`);
    try {
      const objective = [
        "Create starter VYVA marketing copy from an imported Source content record that has little or no body copy.",
        `Content title: ${titleSeed}.`,
        `Source type: ${sourceType}.`,
        sourceId ? `Source ID: ${sourceId}.` : "",
        `Channel: ${channelLabel[currentDraft.channel]}.`,
        `Tone: ${toneLabel}. ${campaignStudioToneGuidance[contentPolishTone]}`,
        "Use the title, source metadata, and channel to produce practical first-draft copy for admin review.",
        "Do not claim clinical outcomes. Keep it warm, specific, and ready to edit before publishing.",
        currentDraft.ctaLabel ? `Existing CTA label: ${currentDraft.ctaLabel}` : "",
        currentDraft.ctaUrl ? `Existing CTA URL: ${currentDraft.ctaUrl}` : "",
        Object.keys(existingMetadata).length ? `Source metadata JSON:\n${JSON.stringify(existingMetadata, null, 2).slice(0, 1800)}` : "",
      ].filter(Boolean).join("\n\n");
      const result = await api<CampaignStudioAiDraftResponse>("/api/admin/marketing/ai/campaign-draft", {
        method: "POST",
        body: JSON.stringify({
          playLabel: "Content starter copy",
          playCategory: "content_starter",
          audienceType: "both",
          channel: currentDraft.channel,
          tone: contentPolishTone,
          targetAudienceName: "Current marketing audience",
          campaignName: titleSeed,
          contentTitle: titleSeed,
          objective,
          subjectSeed: currentDraft.subject.trim() || titleSeed,
          bodySeed: currentDraft.body.trim() || currentDraft.htmlBody.trim() || titleSeed,
          ctaLabel: currentDraft.ctaLabel || "Learn more",
          ctaUrl: currentDraft.ctaUrl || "https://v2.vyva.life",
          language: currentDraft.language || "en",
        }),
      });

      const starter = result.draft;
      const generatedBody = starter.body.trim() || `Draft copy for ${titleSeed}. Review and tailor this before publishing.`;
      const generatedSubject = starter.subject.trim() || currentDraft.subject || titleSeed;
      const generatedCtaLabel = starter.ctaLabel.trim() || currentDraft.ctaLabel || "Learn more";
      const generatedCtaUrl = starter.ctaUrl.trim() || currentDraft.ctaUrl || "https://v2.vyva.life";
      const generatedAt = new Date().toISOString();
      const starterEntry = {
        source: result.source,
        tone: contentPolishTone,
        toneLabel,
        generatedAt,
        previousSubject: currentDraft.subject || null,
        previousBodyPreview: (currentDraft.body || currentDraft.htmlBody).slice(0, 240) || null,
        sourceType,
        sourceId: sourceId || null,
        note: result.note ?? null,
      };
      const previousHistory = Array.isArray(existingMetadata.aiStarterHistory) ? existingMetadata.aiStarterHistory.slice(-4) : [];

      setContentEditDraft((draft) => {
        const baseDraft = draft ?? currentDraft;
        return {
          ...baseDraft,
          subject: generatedSubject,
          body: generatedBody,
          htmlBody: baseDraft.channel === "email" && generatedBody ? emailHtmlFromPlainCopy(generatedBody) : baseDraft.htmlBody,
          ctaLabel: generatedCtaLabel,
          ctaUrl: generatedCtaUrl,
          designJsonText: jsonText({
            ...existingDesign,
            aiStarterCopy: {
              generator: "marketing_content_ai_starter",
              source: result.source,
              tone: contentPolishTone,
              generatedAt,
              modelHints: starter.designJson ?? null,
            },
          }),
          metadataText: jsonText({
            ...existingMetadata,
            aiStarterHistory: [...previousHistory, starterEntry],
          }),
        };
      });
      const note = result.note ? ` ${result.note}` : "";
      setContentFeedback(`AI starter copy generated. Review the draft, then save content.${note}`);
      setContentActionFeedback(`AI starter copy generated for "${titleSeed}". Review and save it.`);
      setMessage("AI starter copy generated.");
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : "AI starter copy could not be generated.";
      setContentFeedback(errorMessage);
      setContentActionFeedback(errorMessage);
      setMessage(errorMessage);
    } finally {
      setContentStarterRunning(false);
    }
  }

