  function showContactWorkQueue(queue: ContactRelationshipWorkQueue) {
    const filter = queue.filterPatch;
    setActiveTab("contacts");
    setContactView("contacts");
    setContactWorkQueueContactIds(queue.contacts.map((contact) => contact.id));
    setSelectedRelationshipContactId(queue.sampleContact?.id ?? null);
    setSearch(filter.search ?? "");
    setAudienceFilter(filter.audience ?? "all");
    setContactSourceFilter(filter.source ?? "all");
    setContactConsentFilter(filter.consent ?? "all");
    setContactLanguageFilter(filter.language ?? "all");
    setContactCategoryFilter(filter.category ?? "all");
    setContactVerticalFilter(filter.vertical ?? "all");
    setContactMarketFilter(filter.market ?? "all");
    setContactListFilter(filter.list ?? "all");
    setConfirmingContactDeleteId(null);
    setContactFeedback(`Showing "${queue.title}" queue: ${queue.countLabel}.`);
  }

  function reviewFirstContactInWorkQueue(queue: ContactRelationshipWorkQueue) {
    const contact = queue.contacts.find((item) => item.consentStatus !== "opted_in") ?? queue.sampleContact ?? queue.contacts[0] ?? null;
    if (!contact) {
      const feedback = `"${queue.title}" has no contacts to review.`;
      setContactFeedback(feedback);
      setMessage(feedback);
      return;
    }
    showContactWorkQueue(queue);
    startContactEdit(contact);
    const contactLabel = contact.fullName || contact.email || contact.phoneNumber || "Unnamed contact";
    const feedback = `Reviewing "${contactLabel}". Update consent or contact details, then save.`;
    setContactFeedback(feedback);
    setMessage(feedback);
  }

  function loadContactWorkQueueInStudio(queue: ContactRelationshipWorkQueue) {
    const play = campaignStudioPlays.find((item) => item.id === queue.playId) ?? campaignStudioPlays[0];
    const isConsentCleanup = queue.key === "consent-cleanup";
    const queueCampaignContacts = isConsentCleanup
      ? queue.contacts.filter((contact) => contact.consentStatus !== "opted_out")
      : queue.contacts;
    const optedOutExcludedCount = isConsentCleanup ? queue.contacts.length - queueCampaignContacts.length : 0;
    if (isConsentCleanup && queueCampaignContacts.length === 0) {
      showContactWorkQueue(queue);
      const feedback = "Only opted-out contacts are in consent cleanup. Keep them out of campaigns and update consent manually if their preference changes.";
      setCampaignStudioFeedback(feedback);
      setMessage(feedback);
      return;
    }
    const relatedAudience = queue.filterPatch.list
      ? audiences.find((audience) => lower(audience.name) === queue.filterPatch.list) ?? bestCampaignStudioAudience(play, audiences)
      : bestCampaignStudioAudience(play, audiences);
    const studioSampleContact = queueCampaignContacts[0] ?? queue.sampleContact;
    const primaryChannel = queue.channels.find((channel) => recipientForChannel(studioSampleContact ?? {
      id: "",
      audienceType: play.audienceType,
      fullName: "",
      email: null,
      phoneNumber: null,
      whatsappNumber: null,
      roleLabel: null,
      companyName: null,
      consentStatus: "unknown",
      source: "vyva",
      tags: [],
      language: null,
      category: null,
      vertical: null,
      market: null,
      lists: [],
      lovableExternalId: null,
    }, channel)) ?? queue.channels[0] ?? play.defaultChannel;
    const selectedChannels = uniqueChannels([primaryChannel, ...queue.channels]);
    const targetAudienceId = isConsentCleanup ? CAMPAIGN_STUDIO_NO_AUDIENCE_ID : relatedAudience?.id ?? "";
    const campaignDraftTargetAudienceId = isConsentCleanup ? "" : targetAudienceId;

    setActiveTab("dashboard");
    setCampaignStudioCategory(play.categoryId);
    updateCampaignStudio({
      playId: play.id,
      channel: primaryChannel,
      selectedChannels,
      targetAudienceId,
      scheduleStartsAt: campaignStudioDefaultSchedule(play),
      toneId: queue.toneId,
      angleId: queue.angleId,
    });
    setCampaignDraft((draft) => ({
      ...draft,
      audienceType: play.audienceType,
      channel: primaryChannel,
      targetAudienceId: campaignDraftTargetAudienceId,
      recipientFilter: isConsentCleanup
        ? "Consent review: pending/unknown only"
        : queue.sampleContact?.email || queue.sampleContact?.fullName || queue.filterPatch.search || "",
      snapshotRecipients: isConsentCleanup ? false : queue.count > 0,
    }));
    if (isConsentCleanup) {
      const pendingCount = queue.contacts.filter((contact) => contact.consentStatus === "pending").length;
      const unknownCount = queue.contacts.filter((contact) => contact.consentStatus === "unknown").length;
      const reachableCount = queueCampaignContacts.filter((contact) => selectedChannels.some((channel) => Boolean(recipientForChannel(contact, channel)))).length;
      setCampaignIntentBrief([
        "Consent re-permission campaign.",
        `Contacts needing review: ${queue.countLabel} (${pendingCount} pending, ${unknownCount} unknown, ${optedOutExcludedCount} opted out).`,
        `Campaign planning pool: ${queueCampaignContacts.length} pending/unknown contact${queueCampaignContacts.length === 1 ? "" : "s"}; ${reachableCount} reachable by ${selectedChannels.map((channel) => channelLabel[channel]).join(" or ")}.`,
        "Do not message opted-out contacts. Exclude them from every send list unless they explicitly opt back in.",
        "Goal: ask pending/unknown contacts to confirm whether they want to receive VYVA updates, with one clear preference/update CTA and no pressure.",
        "Safeguard: keep recipient snapshots off until a reviewed consent audience is saved and approved.",
      ].join("\n"));
      const feedback = `Consent-safe re-permission plan loaded: ${queueCampaignContacts.length} pending/unknown contact${queueCampaignContacts.length === 1 ? "" : "s"}; ${optedOutExcludedCount} opted-out excluded. Recipient snapshots are off until a reviewed consent audience is saved.`;
      setCampaignStudioFeedback(feedback);
      setMessage("Consent-safe campaign plan loaded. Review the AI brief, save a reviewed audience, then decide whether to send.");
    } else {
      setCampaignStudioFeedback(`Relationship queue loaded: ${queue.title}. ${queue.countLabel} are ready for ${selectedChannels.map((channel) => channelLabel[channel]).join(" + ")} planning.`);
      setMessage(`Relationship queue loaded: ${queue.title}. Generate AI copy, review the templates, then create the campaign.`);
    }
  }

  function buildAudienceFromContactWorkQueue(queue: ContactRelationshipWorkQueue) {
    if (queue.count === 0) {
      const feedback = `"${queue.title}" has no contacts to turn into a list yet.`;
      setAudienceFeedback(feedback);
      setMessage(feedback);
      return;
    }
    const isConsentCleanup = queue.key === "consent-cleanup";
    const listContacts = isConsentCleanup
      ? queue.contacts.filter((contact) => contact.consentStatus !== "opted_out")
      : queue.contacts;
    const excludedOptedOutCount = isConsentCleanup ? queue.contacts.length - listContacts.length : 0;
    if (!listContacts.length) {
      const feedback = isConsentCleanup
        ? "Only opted-out contacts are in consent cleanup. Keep them out of campaign lists unless they explicitly opt back in."
        : `"${queue.title}" has no contacts to turn into a list yet.`;
      setAudienceFeedback(feedback);
      setMessage(feedback);
      return;
    }
    const uniqueTextValues = (values: Array<string | null | undefined>, limit = 8) => Array.from(new Set(
      values
        .map((value) => value?.trim())
        .filter((value): value is string => Boolean(value)),
    )).slice(0, limit);
    const contactExternalIds = Array.from(new Set(listContacts.map(contactAudienceMemberId)));
    const rules = {
      source: "relationship_work_queue",
      queue: queue.key,
      title: queue.title,
      channels: queue.channels,
      contactCount: queue.count,
      listContactCount: listContacts.length,
      excludedOptedOutCount,
      requiresReview: isConsentCleanup,
      audienceTypes: uniqueTextValues(listContacts.map((contact) => contact.audienceType)),
      consentStatuses: uniqueTextValues(listContacts.map((contact) => contact.consentStatus)),
      languages: uniqueTextValues(listContacts.map((contact) => contact.language)),
      categories: uniqueTextValues(listContacts.map((contact) => contact.category)),
      verticals: uniqueTextValues(listContacts.map((contact) => contact.vertical)),
      markets: uniqueTextValues(listContacts.map((contact) => contact.market)),
      lists: uniqueTextValues(listContacts.flatMap((contact) => contact.lists), 12),
      tags: uniqueTextValues(listContacts.flatMap((contact) => contact.tags), 12),
    };
    const listCountLabel = `${listContacts.length} contact${listContacts.length === 1 ? "" : "s"}`;
    const pendingUnknownLabel = `${listContacts.length} pending/unknown contact${listContacts.length === 1 ? "" : "s"}`;
    const consentExclusionNote = excludedOptedOutCount
      ? ` Excluded ${excludedOptedOutCount} opted-out contact${excludedOptedOutCount === 1 ? "" : "s"}.`
      : "";

    setActiveTab("contacts");
    setContactView("lists");
    setEditingAudienceId(null);
    setAudienceEditDraft(null);
    setConfirmingAudienceDeleteId(null);
    setAudienceDraft({
      name: isConsentCleanup ? "Consent review list" : `${queue.title} list`,
      listType: "static",
      description: isConsentCleanup
        ? `${queue.detail} Built from ${pendingUnknownLabel}.${consentExclusionNote}`
        : `${queue.detail} Built from ${queue.countLabel}.`,
      rulesText: jsonText(rules),
      contactExternalIds: contactExternalIds.join("\n"),
    });
    setAudienceFeedback(isConsentCleanup
      ? `Consent cleanup queue loaded as a review list with ${listCountLabel}.${consentExclusionNote}`
      : `${queue.title} queue loaded as a list with ${queue.countLabel}. Review and save the audience.`);
    setMessage(isConsentCleanup
      ? "Consent review list loaded into the audience builder."
      : `${queue.title} queue loaded into the audience builder.`);
  }

  function loadFilteredAudienceIntoBuilder() {
    if (visibleContacts.length === 0) {
      const feedback = "No visible contacts match the current filters.";
      setAudienceFeedback(feedback);
      setMessage(feedback);
      return;
    }

    setActiveTab("contacts");
    setContactView("lists");
    setEditingAudienceId(null);
    setAudienceEditDraft(null);
    setConfirmingAudienceDeleteId(null);
    setAudienceDraft({
      name: filteredAudienceName.trim() || filteredAudienceDefaultName,
      listType: "static",
      description: filteredAudienceDescription,
      rulesText: filteredAudienceRulesText,
      contactExternalIds: filteredAudienceMemberIds.join("\n"),
    });
    setAudienceFeedback(`Loaded ${visibleContacts.length} filtered contact${visibleContacts.length === 1 ? "" : "s"} into the list builder.`);
    setMessage("Filtered audience loaded into the list builder.");
  }

  async function createAudienceFromCurrentFilters(openInCampaignStudio = false) {
    if (visibleContacts.length === 0) {
      const feedback = "No visible contacts match the current filters.";
      setAudienceFeedback(feedback);
      setMessage(feedback);
      return;
    }

    setAudienceSaving(true);
    setAudienceFeedback("Saving filtered audience...");
    try {
      const result = await api<{ audience: MarketingAudience }>("/api/admin/marketing/audiences", {
        method: "POST",
        body: JSON.stringify({
          name: filteredAudienceName.trim() || filteredAudienceDefaultName,
          listType: "static",
          description: filteredAudienceDescription,
          rules: filteredAudienceRules,
          contactExternalIds: filteredAudienceMemberIds,
          source: "vyva_filtered_segment",
          metadata: {
            created_from: "filtered_contact_view",
            filterLabels: activeContactFilterLabels,
            createdAt: new Date().toISOString(),
          },
        }),
      });
      setAudiences((current) => [result.audience, ...current.filter((audience) => audience.id !== result.audience.id)]);
      setFilteredAudienceName("");
      if (openInCampaignStudio) {
        const strategy = audienceStrategyBrief(result.audience, contacts);
        loadAudienceStrategyInStudio(result.audience, strategy);
        setAudienceFeedback(`Created filtered audience "${result.audience.name}" and loaded it into the campaign studio.`);
      } else {
        setActiveTab("contacts");
        setContactView("lists");
        setEditingAudienceId(result.audience.id);
        setAudienceEditDraft(audienceEditDraftFromAudience(result.audience));
        setConfirmingAudienceDeleteId(null);
        setAudienceFeedback(`Created filtered audience "${result.audience.name}" with ${filteredAudienceMemberIds.length} member${filteredAudienceMemberIds.length === 1 ? "" : "s"}.`);
        setMessage(`Filtered audience created: ${result.audience.name}.`);
        scrollToContentPanel(audienceEditorPanelRef);
      }
      await refreshAll();
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : "Filtered audience could not be created.";
      setAudienceFeedback(errorMessage);
      setMessage(errorMessage);
    } finally {
      setAudienceSaving(false);
    }
  }

  function relationshipCampaignIntentForContact(
    contact: MarketingContact,
    selectedChannels: Channel[],
    relatedAudience: MarketingAudience | null,
    template: ContentTemplate | null = null,
  ) {
    const activeBrief = selectedRelationshipContact?.id === contact.id ? contactRelationshipBrief : null;
    const isB2bContact = contact.audienceType === "b2b" || Boolean(contact.companyName || contact.roleLabel);
    const contactName = contact.fullName || contact.email || contact.phoneNumber || "this contact";
    const roleContext = [contact.roleLabel, contact.companyName].filter(Boolean).join(" at ");
    const segmentContext = [contact.market, contact.vertical, contact.category, contact.language].filter(Boolean).join(" / ");
    const audienceName = relatedAudience?.name ?? contact.lists[0] ?? contact.audienceType.toUpperCase();
    const route = selectedChannels.map((channel) => channelLabel[channel]).join(" + ");
    const goal = isB2bContact
      ? "open a partner conversation, reply, or demo request"
      : "help the family or caregiver take one useful next step";

    return [
      `Relationship campaign for ${contactName}.`,
      roleContext ? `Contact context: ${roleContext}.` : "",
      `Audience/list: ${audienceName}.`,
      `Channels: ${route}.`,
      template ? `Starter template: "${template.title}" on ${channelLabel[template.channel]}.` : activeBrief?.starter ? `Starter: ${activeBrief.starter}` : "",
      activeBrief?.angle ? `Angle: ${activeBrief.angle}` : segmentContext ? `Angle: make the message specific to ${segmentContext}.` : "",
      activeBrief?.opener ? `Opener: ${activeBrief.opener}` : "",
      `Consent status: ${contact.consentStatus}.`,
      activeBrief?.risk ? `Watch item: ${activeBrief.risk}` : "",
      `Goal: ${goal}.`,
    ].filter(Boolean).join("\n");
  }

  function relationshipAudienceForContact(contact: MarketingContact) {
    const contactKeys = new Set([
      ...lookupKeysForExternalId(contact.id, ["contact"]),
      ...lookupKeysForExternalId(contact.lovableExternalId, ["contact"]),
    ]);
    return audiences.find((audience) => {
      if (contactMatchesAudienceList(contact, audience)) return true;
      return audience.memberPreview.some((member) => {
        if (member.id === contact.id) return true;
        return lookupKeysForExternalId(member.contactExternalId || member.lovableExternalId, ["contact"])
          .some((key) => contactKeys.has(key));
      });
    }) ?? null;
  }

  function focusCampaignStudioForRelationshipContact(contact: MarketingContact, relatedAudienceOverride?: MarketingAudience | null) {
    const isB2bContact = contact.audienceType === "b2b" || Boolean(contact.companyName || contact.roleLabel);
    const play = campaignStudioPlays.find((item) => item.id === (isB2bContact ? "b2b-partner-outreach" : "family-confidence")) ?? campaignStudioPlays[0];
    const relatedAudience = relatedAudienceOverride ?? relationshipAudienceForContact(contact) ?? bestCampaignStudioAudience(play, audiences);
    const primaryChannel: Channel = contact.email
      ? "email"
      : (contact.whatsappNumber || contact.phoneNumber)
        ? "whatsapp"
        : isB2bContact
          ? "linkedin"
          : play.defaultChannel;
    const selectedChannels = uniqueChannels([
      primaryChannel,
      ...(isB2bContact ? ["email", "linkedin"] as Channel[] : ["email", "whatsapp"] as Channel[]),
    ]);
    setActiveTab("dashboard");
    setCampaignStudioCategory(play.categoryId);
    updateCampaignStudio({
      playId: play.id,
      channel: primaryChannel,
      selectedChannels,
      targetAudienceId: relatedAudience?.id ?? "",
      scheduleStartsAt: campaignStudioDefaultSchedule(play),
      toneId: isB2bContact ? "expert" : "warm",
      angleId: contact.market ? "local" : "balanced",
    });
    setCampaignDraft((draft) => ({
      ...draft,
      audienceType: play.audienceType,
      channel: primaryChannel,
      targetAudienceId: relatedAudience?.id ?? "",
      recipientFilter: contact.email || contact.fullName || contact.whatsappNumber || contact.phoneNumber || "",
      snapshotRecipients: Boolean(recipientForChannel(contact, primaryChannel)),
    }));
    setCampaignIntentBrief(relationshipCampaignIntentForContact(contact, selectedChannels, relatedAudience));
    setCampaignStudioFeedback(`Studio focused on ${contact.fullName || contact.email || "this contact"} with ${selectedChannels.map((channel) => channelLabel[channel]).join(" + ")}.`);
    setMessage(`Campaign studio is ready for ${contact.fullName || contact.email || "this contact"}. Generate AI copy or use the recommended channel pack.`);
  }

  async function buildCampaignForRelationshipContact(contact: MarketingContact) {
    const isB2bContact = contact.audienceType === "b2b" || Boolean(contact.companyName || contact.roleLabel);
    const play = campaignStudioPlays.find((item) => item.id === (isB2bContact ? "b2b-partner-outreach" : "family-confidence")) ?? campaignStudioPlays[0];
    const existingAudience = relationshipAudienceForContact(contact);
    if (existingAudience) {
      focusCampaignStudioForRelationshipContact(contact, existingAudience);
      return;
    }

    const contactName = contact.fullName || contact.email || contact.phoneNumber || contact.whatsappNumber || "Unnamed contact";
    const contactExternalId = contactAudienceMemberId(contact);
    setAudienceSaving(true);
    setContactFeedback(`Creating a reusable relationship list for "${contactName}"...`);
    try {
      const result = await api<{ audience: MarketingAudience }>("/api/admin/marketing/audiences", {
        method: "POST",
        body: JSON.stringify({
          name: `${contactName} relationship list`,
          listType: "static",
          description: `Single-contact relationship list for ${contactName}. Built from the contact relationship view so campaigns can snapshot a clear audience instead of relying on a text filter.`,
          rules: {
            source: "single_contact_relationship",
            contactId: contact.id,
            contactExternalId,
            audienceType: contact.audienceType,
            consentStatus: contact.consentStatus,
            language: contact.language,
            category: contact.category,
            vertical: contact.vertical,
            market: contact.market,
            tags: contact.tags,
          },
          contactExternalIds: [contactExternalId],
          source: "vyva_relationship_contact",
          metadata: {
            created_from: "relationship_contact_build_campaign",
            createdAt: new Date().toISOString(),
            contact: {
              id: contact.id,
              lovableExternalId: contact.lovableExternalId,
              fullName: contact.fullName,
              email: contact.email,
              companyName: contact.companyName,
              roleLabel: contact.roleLabel,
            },
          },
        }),
      });
      setAudiences((current) => [result.audience, ...current.filter((audience) => audience.id !== result.audience.id)]);
      focusCampaignStudioForRelationshipContact(contact, result.audience);
      setAudienceFeedback(`Created "${result.audience.name}" and loaded it into the campaign studio.`);
      setContactFeedback(`Created "${result.audience.name}" for ${contactName}.`);
      await refreshAll();
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : "Relationship list could not be created.";
      setAudienceFeedback(errorMessage);
      setContactFeedback(errorMessage);
      setMessage(errorMessage);
    } finally {
      setAudienceSaving(false);
    }
  }

  function startRelationshipCampaignFromTemplate(contact: MarketingContact, template: ContentTemplate) {
    const relatedAudience = contactRelationshipAudiences[0] ?? bestCampaignStudioAudience(
      campaignStudioPlays.find((item) => item.audienceType === template.audienceType) ?? campaignStudioPlays[0],
      audiences,
    );
    startCampaignFromContentTemplate(template);
    setCampaignDraft((draft) => ({
      ...draft,
      audienceType: template.audienceType,
      channel: template.channel,
      targetAudienceId: relatedAudience?.id ?? "",
      recipientFilter: contact.email || contact.fullName || contact.whatsappNumber || contact.phoneNumber || "",
      snapshotRecipients: Boolean(recipientForChannel(contact, template.channel)),
    }));
    setCampaignIntentBrief(relationshipCampaignIntentForContact(contact, [template.channel], relatedAudience, template));
    setCampaignStudioFeedback(`Template "${template.title}" applied for ${contact.fullName || contact.email || "this contact"}.`);
    setMessage(`Template "${template.title}" is ready for ${contact.fullName || contact.email || "this contact"}. Save the content draft, then add the campaign.`);
  }

